}
function loadRun() {
  try {
    const parsed = JSON.parse(localStorage.getItem(RUN_KEY) || 'null');
    if (!parsed || parsed.version !== 2 || !parsed.map || parsed.hp <= 0 || parsed.won) return null;
    return parsed;
  } catch {
