    title="${esc(reason || cardText(def, card.upgraded))}" ${mode === 'hand' && !playable ? 'aria-disabled="true"' : ''}>
    <span class="card-cost">${def.cost}</span>
    <span class="card-art">${isOrb ? orbArt() : icon(def.icon)}<i class="card-art-glow"></i></span>
