const MAP_W = 640;
const MAP_H = 1330;
const LANE_X = [132, 320, 508];
const START_Y = 1238;
const ROW_Y = (floor) => 1160 - floor * 104;

function nodePosition(node) {
  return { x: LANE_X[node.lane] ?? 320, y: ROW_Y(node.floor) };
}

function mapDecor() {
