322: function cardNumbers(def, upgraded) {
323:   const ops = modifiedOps(def, upgraded);
324:   const find = (name) => ops.find((operation) => operation.op === name) || {};
325:   const damage = find('damage');
326:   const block = find('block');
327:   const draw = find('draw');
328:   const focus = ops.find((operation) => operation.op === 'self' && operation.status === 'focus') || {};
329:   const thorns = ops.find((operation) => operation.op === 'self' && operation.status === 'thorns') || {};
330:   const regen = ops.find((operation) => operation.op === 'self' && operation.status === 'regen') || {};
331:   const weak = ops.find((operation) => operation.op === 'status' && operation.status === 'weak') || {};
332:   const vulnerable = ops.find((operation) => operation.op === 'status' && operation.status === 'vulnerable') || {};
333:   const burn = ops.find((operation) => operation.op === 'status' && operation.status === 'burn') || {};
334:   const stun = ops.find((operation) => operation.op === 'status' && operation.status === 'stun') || {};
335:   const heal = find('heal');
336:   const execute = find('execute');
337:   const catchOp = find('catch');
338:   return {
339:     ops, damage: damage.amount || 0, block: block.amount || 0, draw: draw.amount || 0,
340:     focus: focus.amount || 0, thorns: thorns.amount || 0, regen: regen.amount || 0,
341:     weak: weak.amount || 0, vulnerable: vulnerable.amount || 0, burn: burn.amount || 0,
342:     stun: stun.amount || 0, heal: heal.amount || 0, bonus: execute.amount || 0,
343:     threshold: catchOp.threshold || 0, catchBonus: catchOp.bonus || 0,
344:     chance: catchOp.threshold ? captureChance(catchOp.threshold, catchOp.bonus, catchOp.threshold) : 0,
345:   };
346: }
347: 
348: function cardText(def, upgraded = false) {
349:   const n = cardNumbers(def, upgraded);
350:   return def.text
351:     .replace('{damage}', n.damage)
352:     .replace('{block}', n.block)
353:     .replace('{draw}', n.draw)
354:     .replace('{focus}', n.focus)
355:     .replace('{thorns}', n.thorns)
356:     .replace('{regen}', n.regen)
357:     .replace('{weak}', n.weak)
358:     .replace('{vulnerable}', n.vulnerable)
359:     .replace('{burn}', n.burn)
360:     .replace('{stun}', n.stun)
361:     .replace('{heal}', n.heal)
362:     .replace('{bonus}', n.bonus)
363:     .replace('{threshold}', Math.round(n.threshold * 100))
364:     .replace('{chance}', Math.round(n.chance * 100));
365: }
