367: function cardHTML(card, { index = 0, count = 1, mode = 'hand', reward = false } = {}) {
368:   const def = CARDS[card.id];
369:   if (!def) return '';
370:   const type = TYPES[def.type] || TYPES.stone;
371:   const playable = mode === 'hand' ? canPlayCard(card) : true;
372:   const reason = mode === 'hand' ? cardBlockReason(card) : '';
373:   const isOrb = def.kind === 'bind';
374:   return `<button type="button" class="card kind-${def.kind} ${card.upgraded ? 'upgraded' : ''} ${playable ? 'playable' : 'unplayable'} ${isOrb ? 'orb-card' : ''}"
375:     data-card-uid="${reward ? '' : card.uid}" data-reward-index="${reward ? index : ''}" style="--i:${index};--n:${count};--tc:${type.color};--td:${type.deep};--ts:${type.soft}"
376:     title="${esc(reason || cardText(def, card.upgraded))}" ${mode === 'hand' && !playable ? 'aria-disabled="true"' : ''}>
377:     <span class="card-cost">${def.cost}</span>
378:     <span class="card-art">${isOrb ? orbArt() : icon(def.icon)}<i class="card-art-glow"></i></span>
379:     <span class="card-name">${def.name}${card.upgraded ? '<sup>+</sup>' : ''}</span>
380:     <span class="card-sub">${type.name} · ${CARD_KIND[def.kind] || def.kind}${def.exhaust ? ' · Exhaust' : ''}</span>
381:     <span class="card-rule"></span>
382:     <span class="card-text">${esc(cardText(def, card.upgraded))}</span>
383:     ${def.kind === 'attack' ? `<span class="card-strike">${icon('claw')}</span>` : ''}
384:     ${def.exhaust ? '<span class="card-exhaust">Exhaust</span>' : ''}
385:   </button>`;
386: }
