388: function canPlayCard(card) {
389:   if (!combat || combat.phase !== 'player' || busy) return false;
390:   const def = CARDS[card.id];
391:   if (!def) return false;
392:   if ((combat.energy || 0) < def.cost) return false;
393:   const catchOp = modifiedOps(def, card.upgraded).find((operation) => operation.op === 'catch');
394:   if (catchOp) {
395:     if (combat.enemy.isBoss) return false;
396:     const threshold = combat.enemy.isElite ? Math.min(catchOp.threshold, 0.4) : catchOp.threshold;
397:     if (combat.enemy.hp / combat.enemy.maxHp > threshold) return false;
398:   }
399:   return true;
400: }
401: function cardBlockReason(card) {
402:   const def = CARDS[card.id];
403:   if (!def || !combat) return '';
404:   if (combat.phase !== 'player' || busy) return 'Wait for your turn.';
405:   if (combat.energy < def.cost) return 'Not enough energy.';
406:   const catchOp = modifiedOps(def, card.upgraded).find((operation) => operation.op === 'catch');
407:   if (catchOp) {
408:     if (combat.enemy.isBoss) return 'The Hollow Warden cannot be bound.';
409:     const threshold = combat.enemy.isElite ? Math.min(catchOp.threshold, 0.4) : catchOp.threshold;
410:     if (combat.enemy.hp / combat.enemy.maxHp > threshold) return `Weaken the beast below ${Math.round(threshold * 100)}% HP first.`;
411:   }
412:   return '';
413: }
