1515: function resolveOperation(operation, card) {
1516:   const def = CARDS[card.id];
1517:   switch (operation.op) {
1518:     case 'damage': {
1519:       hitEnemy(operation.amount, { times: operation.times || 1, source: 'card' });
1520:       if (combat.enemy.hp <= 0) return 'dead';
1521:       break;
1522:     }
1523:     case 'execute': {
1524:       if (combat.enemy.hp / combat.enemy.maxHp < operation.threshold) {
1525:         hitEnemy(operation.amount, { source: 'card' });
1526:         if (combat.enemy.hp <= 0) return 'dead';
1527:       }
1528:       break;
1529:     }
1530:     case 'block': {
1531:       const amount = operation.amount + (combat.status.dex || 0);
1532:       combat.playerBlock += amount;
1533:       pendingFx.push({ target: 'player', text: `+${amount}`, kind: 'block' });
1534:       sfx.block();
1535:       break;
1536:     }
1537:     case 'draw': {
1538:       drawCards(operation.amount);
1539:       sfx.draw();
1540:       break;
1541:     }
1542:     case 'energy': {
1543:       combat.energy += operation.amount;
1544:       pendingFx.push({ target: 'player', text: `+${operation.amount} energy`, kind: 'energy' });
1545:       break;
1546:     }
1547:     case 'status': {
1548:       const target = operation.target === 'player' ? combat.status : combat.enemy.status;
1549:       target[operation.status] = (target[operation.status] || 0) + operation.amount;
1550:       pendingFx.push({ target: operation.target === 'player' ? 'player' : 'enemy', text: `${STATUS_INFO[operation.status]?.name || operation.status} ${operation.amount}`, kind: 'status' });
1551:       break;
1552:     }
1553:     case 'self': {
1554:       combat.status[operation.status] = (combat.status[operation.status] || 0) + operation.amount;
1555:       pendingFx.push({ target: 'player', text: `${STATUS_INFO[operation.status]?.name || operation.status} ${operation.amount}`, kind: 'status' });
1556:       break;
1557:     }
1558:     case 'heal': {
1559:       const before = run.hp;
1560:       run.hp = Math.min(run.maxHp, run.hp + operation.amount);
1561:       pendingFx.push({ target: 'player', text: `+${run.hp - before}`, kind: 'heal' });
1562:       sfx.heal();
1563:       break;
1564:     }
1565:     case 'catch': {
1566:       return attemptCatch(operation.threshold, operation.bonus || 0);
1567:     }
1568:     case 'add': {
1569:       combat.status[operation.status] = (combat.status[operation.status] || 0) + operation.amount;
1570:       break;
1571:     }
1572:     default: break;
1573:   }
1574:   void def;
1575:   return '';
1576: }
