1578: function hitEnemy(base, { times = 1, source = 'card', ignoreBlock = false } = {}) {
1579:   for (let i = 0; i < times; i++) {
1580:     let amount = base + (combat.status.focus || 0);
1581:     if (source === 'card' && combat.firstAttack && combat.firstAttackBonus) {
1582:       amount += combat.firstAttackBonus;
1583:       combat.firstAttack = false;
1584:     } else if (source === 'card') {
1585:       combat.firstAttack = false;
1586:     }
1587:     if (combat.status.weak > 0) amount = Math.floor(amount * 0.75);
1588:     if (combat.enemy.status.vulnerable > 0) amount = Math.floor(amount * 1.5);
1589:     amount = Math.max(0, amount);
1590:     let lost = amount;
1591:     if (!ignoreBlock) {
1592:       const blocked = Math.min(combat.enemy.block, lost);
1593:       combat.enemy.block -= blocked;
1594:       lost -= blocked;
1595:     }
1596:     combat.enemy.hp = Math.max(0, combat.enemy.hp - lost);
1597:     run.stats.damage += lost;
1598:     if (lost > 0) {
1599:       pendingFx.push({ target: 'enemy', text: `-${lost}`, kind: 'damage' });
1600:       sfx.hit();
1601:       shakeZone('enemy');
1602:     } else {
1603:       pendingFx.push({ target: 'enemy', text: 'BLOCKED', kind: 'blocked' });
1604:       sfx.block();
1605:     }
1606:     combat.log = `${combat.enemy.name} takes ${lost} damage.`;
1607:     if (combat.enemy.status.thorns > 0 && lost > 0) {
1608:       damagePlayer(combat.enemy.status.thorns, { ignoreBlock: true, source: 'thorns' });
1609:     }
1610:     if (combat.enemy.hp <= 0) break;
1611:   }
1612: }
