1614: function damagePlayer(amount, { ignoreBlock = false, source = 'enemy' } = {}) {
1615:   let lost = Math.max(0, amount);
1616:   if (!ignoreBlock) {
1617:     const blocked = Math.min(combat.playerBlock, lost);
1618:     combat.playerBlock -= blocked;
1619:     lost -= blocked;
1620:     if (blocked > 0) pendingFx.push({ target: 'player', text: `BLOCKED ${blocked}`, kind: 'blocked' });
1621:   }
1622:   run.hp = Math.max(0, run.hp - lost);
1623:   if (lost > 0) {
1624:     pendingFx.push({ target: 'player', text: `-${lost}`, kind: 'damage' });
1625:     sfx.hit();
1626:     shakeZone('player');
1627:     combat.log = source === 'thorns' ? `Thorns bite back for ${lost}.` : `You take ${lost} damage.`;
1628:   }
1629:   if (run.hp <= 0) combat.log = 'The mountain grows quiet.';
1630: }
