1632: function attemptCatch(threshold, bonus) {
1633:   const enemy = combat.enemy;
1634:   if (enemy.isBoss) {
1635:     pendingFx.push({ target: 'enemy', text: 'UNBINDABLE', kind: 'blocked' });
1636:     sfx.error();
1637:     return '';
1638:   }
1639:   if (enemy.hp / enemy.maxHp > threshold) {
1640:     pendingFx.push({ target: 'enemy', text: 'TOO STRONG', kind: 'blocked' });
1641:     sfx.error();
1642:     return '';
1643:   }
1644:   const chance = captureChance(threshold, bonus);
1645:   const success = Math.random() < chance;
1646:   combat.log = `Pocket Orb — ${Math.round(chance * 100)}% to bind.`;
1647:   if (success) {
1648:     enemy.hp = 0;
1649:     combat.phase = 'won';
1650:     combat.log = `${enemy.name} is bound.`;
1651:     pendingFx.push({ target: 'enemy', text: 'BOUND', kind: 'catch' });
1652:     playCatchBurst();
1653:     sfx.catchStart();
1654:     setTimeout(() => sfx.catchWin(), 430);
1655:     return 'caught';
1656:   }
1657:   enemy.status.focus = (enemy.status.focus || 0) + 1;
1658:   combat.status.catch = 0;
1659:   pendingFx.push({ target: 'enemy', text: 'BROKE FREE', kind: 'blocked' });
1660:   pendingFx.push({ target: 'enemy', text: '+1 Focus', kind: 'status' });
1661:   combat.log = `${enemy.name} breaks free and grows fierce.`;
1662:   sfx.error();
1663:   shakeZone('enemy');
1664:   return '';
1665: }
