/* ============================================================
   WILDSPIRE — visual system
   Palette: deep pine night, lantern gold, river mint
   ============================================================ */

:root {
  --bg: #07110f;
  --bg-2: #0a1917;
  --bg-3: #0e211e;
  --panel: rgba(11, 26, 23, 0.82);
  --panel-solid: #0c1b18;
  --panel-hi: rgba(22, 44, 38, 0.9);
  --line: rgba(233, 196, 122, 0.18);
  --line-soft: rgba(126, 230, 201, 0.14);
  --gold: #e9c47a;
  --gold-hi: #ffe6ad;
  --gold-deep: #a97c3f;
  --mint: #7ee6c9;
  --mint-deep: #2e9b7d;
  --ink: #eaf2e9;
  --ink-soft: #c3d2c8;
  --muted: #8fa79e;
  --dim: #647a72;
  --danger: #f17f9b;
  --danger-deep: #8f2948;
  --blue: #74d4ed;
  --shadow: 0 24px 70px rgba(0, 0, 0, 0.55);
  --serif: "Iowan Old Style", "Palatino Linotype", Palatino, "Book Antiqua", Georgia, serif;
  --sans: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --mono: ui-monospace, "SFMono-Regular", "Cascadia Mono", Menlo, Consolas, monospace;
  --card-w: 132px;
  --card-h: 188px;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  height: 100%;
  background: var(--bg);
}

body {
  color: var(--ink);
  font-family: var(--sans);
  font-size: 15px;
  line-height: 1.45;
  overflow: hidden;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  overscroll-behavior: none;
}

body::before {
  content: "";
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  background:
    radial-gradient(120% 90% at 50% -10%, rgba(34, 82, 68, 0.38), transparent 58%),
    radial-gradient(80% 70% at 100% 110%, rgba(112, 78, 38, 0.16), transparent 60%),
    linear-gradient(180deg, #07110f 0%, #050d0c 100%);
}

button { font: inherit; color: inherit; }
button:focus-visible, [tabindex]:focus-visible {
  outline: 2px solid var(--mint);
  outline-offset: 3px;
}
::selection { background: rgba(233, 196, 122, 0.3); color: #fff; }

#app { position: relative; z-index: 1; height: 100dvh; }

#motes {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  opacity: 0.85;
}

#modal-root { position: relative; z-index: 60; }
#toast {
  position: fixed;
  right: max(18px, env(safe-area-inset-right));
  bottom: max(18px, env(safe-area-inset-bottom));
  z-index: 90;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 8px;
  pointer-events: none;
}

.icon {
  width: 1em;
  height: 1em;
  display: inline-block;
  flex: 0 0 auto;
  vertical-align: -0.14em;
}

.screen {
  position: relative;
  width: 100%;
  height: 100dvh;
  overflow: hidden;
}

.muted { color: var(--muted); }
.small { font-size: 0.78rem; }
kbd {
  font-family: var(--mono);
  font-size: 0.68em;
  padding: 2px 6px;
  border-radius: 5px;
  border: 1px solid rgba(233, 196, 122, 0.28);
  background: rgba(0, 0, 0, 0.35);
  color: var(--gold);
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.06) inset;
}

/* ------------------------------------------------------------
   Buttons
   ------------------------------------------------------------ */

.btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  border: 1px solid transparent;
  border-radius: 12px;
  padding: 11px 20px;
  font-family: var(--sans);
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  cursor: pointer;
  transition: transform 0.16s ease, box-shadow 0.2s ease, background 0.2s ease, border-color 0.2s ease;
  text-decoration: none;
  white-space: nowrap;
}
.btn .icon { font-size: 1.1em; }
.btn:hover { transform: translateY(-1px); }
.btn:active { transform: translateY(1px) scale(0.99); }

.btn-primary {
  color: #1a1206;
  background:
    linear-gradient(180deg, #ffe6ad 0%, #e9c47a 46%, #c79a51 100%);
  border-color: #ffe6ad;
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.55) inset,
    0 8px 24px rgba(233, 196, 122, 0.25),
    0 0 0 1px rgba(0, 0, 0, 0.25);
}
.btn-primary:hover {
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.65) inset,
    0 10px 34px rgba(233, 196, 122, 0.4),
    0 0 0 1px rgba(0, 0, 0, 0.25);
}

.btn-ghost {
  color: var(--ink-soft);
  background: rgba(255, 255, 255, 0.035);
  border-color: rgba(233, 196, 122, 0.26);
}
.btn-ghost:hover {
  color: var(--ink);
  border-color: rgba(233, 196, 122, 0.56);
  background: rgba(233, 196, 122, 0.08);
}

.btn-danger {
  color: #ffd9e1;
  background: rgba(143, 41, 72, 0.18);
  border-color: rgba(241, 127, 155, 0.42);
}
.btn-danger:hover { background: rgba(143, 41, 72, 0.34); border-color: var(--danger); }

.btn-round {
  width: 44px;
  height: 44px;
  padding: 0;
  border-radius: 50%;
  color: var(--gold);
  background: rgba(7, 17, 15, 0.62);
  border-color: rgba(233, 196, 122, 0.3);
  backdrop-filter: blur(8px);
}
.btn-round:hover { border-color: var(--gold); background: rgba(233, 196, 122, 0.1); }

.btn-small {
  padding: 7px 13px;
  font-size: 0.66rem;
  border-radius: 8px;
  color: var(--ink);
  background: rgba(233, 196, 122, 0.1);
  border-color: rgba(233, 196, 122, 0.32);
}
.btn-small:hover { background: rgba(233, 196, 122, 0.2); }
.btn-small.disabled, .btn-small:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  transform: none;
}

.btn-hero {
  padding: 16px 36px;
  font-size: 0.88rem;
  letter-spacing: 0.14em;
  border-radius: 14px;
}
.btn-hero .icon { font-size: 1.3em; }

/* ------------------------------------------------------------
   Logo
   ------------------------------------------------------------ */

.logo {
  display: inline-flex;
  align-items: center;
  gap: 10px;
}
.logo-mark {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border-radius: 50%;
  color: var(--gold);
  border: 1px solid rgba(233, 196, 122, 0.4);
  background: radial-gradient(circle at 50% 30%, rgba(233, 196, 122, 0.2), rgba(7, 17, 15, 0.4));
  box-shadow: 0 0 22px rgba(233, 196, 122, 0.16);
}
.logo-mark .icon { width: 20px; height: 20px; }
.logo-word {
  font-family: var(--serif);
  font-size: 1.42rem;
  font-weight: 600;
  letter-spacing: 0.13em;
  color: var(--gold-hi);
  line-height: 1;
}
.logo-word span {
  background: linear-gradient(180deg, #bff3e3, #6fcdb1);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.logo.small .logo-mark { width: 32px; height: 32px; }
.logo.small .logo-mark .icon { width: 17px; height: 17px; }
.logo.small .logo-word { font-size: 1.08rem; }

/* ------------------------------------------------------------
   Title screen
   ------------------------------------------------------------ */

.title-screen {
  overflow-y: auto;
  overflow-x: hidden;
  background: #06100e;
}
.title-scenery {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  pointer-events: none;
}
.title-vignette {
  position: fixed;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(90% 70% at 50% 44%, rgba(4, 12, 11, 0.12) 0%, rgba(4, 12, 11, 0.62) 68%, rgba(3, 9, 8, 0.92) 100%),
    linear-gradient(180deg, rgba(3, 9, 8, 0.55) 0%, transparent 28%, transparent 62%, rgba(3, 9, 8, 0.8) 100%);
}
.title-stars circle { animation: twinkle 5s ease-in-out infinite alternate; }
.title-stars circle:nth-child(2n) { animation-delay: 1.8s; }
.title-stars circle:nth-child(3n) { animation-delay: 3.2s; }

.title-mote {
  position: absolute;
  width: var(--s);
  height: var(--s);
  border-radius: 50%;
  background: #f6dda4;
  box-shadow: 0 0 8px rgba(246, 221, 164, 0.9);
  opacity: 0;
  animation: moteDrift var(--t) linear var(--d) infinite;
}

.title-content {
  position: relative;
  z-index: 2;
  width: min(1040px, 100%);
  min-height: 100dvh;
  margin: 0 auto;
  padding: clamp(26px, 5vh, 60px) clamp(18px, 4vw, 40px) clamp(70px, 10vh, 110px);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  gap: clamp(8px, 1.3vh, 15px);
}

.title-kicker {
  display: flex;
  align-items: center;
  gap: 14px;
  font-size: 0.64rem;
  font-weight: 700;
  letter-spacing: 0.42em;
  color: var(--gold);
  text-transform: uppercase;
  text-shadow: 0 2px 12px rgba(0, 0, 0, 0.8);
}
.title-kicker span {
  display: block;
  width: clamp(24px, 5vw, 58px);
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(233, 196, 122, 0.7));
}
.title-kicker span:last-child { transform: scaleX(-1); }

.title-logo {
  margin: 0;
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: 0.02em;
  font-family: var(--serif);
  font-size: clamp(3.9rem, 10.5vw, 8.4rem);
  font-weight: 600;
  line-height: 0.86;
  letter-spacing: 0.055em;
  filter: drop-shadow(0 14px 34px rgba(0, 0, 0, 0.65));
}
.title-logo span:first-child {
  background: linear-gradient(180deg, #fff8df 0%, #f3d694 38%, #d3a55a 76%, #9d6f34 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.title-logo span:last-child {
  background: linear-gradient(180deg, #eafff6 0%, #b4f2df 34%, #74d6bb 72%, #339277 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.title-pledge {
  margin: 2px 0 0;
  font-family: var(--serif);
  font-size: clamp(0.98rem, 1.7vw, 1.24rem);
  line-height: 1.55;
  color: #cfdcd4;
  text-shadow: 0 2px 14px rgba(0, 0, 0, 0.8);
}
.title-pledge em {
  color: var(--gold-hi);
  font-style: italic;
}

.starter-label {
  margin-top: clamp(6px, 1.4vh, 14px);
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--gold);
}
.starter-label > span:first-child { color: var(--ink-soft); }
.starter-label i {
  display: block;
  width: 42px;
  height: 1px;
  background: rgba(233, 196, 122, 0.32);
}
.starter-count { color: var(--dim); font-weight: 500; letter-spacing: 0.16em; }

.starter-rail {
  width: min(900px, 100%);
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: clamp(9px, 1.4vw, 16px);
  margin-top: 4px;
}

.starter-choice {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  min-width: 0;
  padding: 12px 13px 13px;
  border-radius: 17px;
  border: 1px solid color-mix(in srgb, var(--tc) 28%, rgba(255, 255, 255, 0.08));
  background:
    radial-gradient(120% 80% at 50% 0%, color-mix(in srgb, var(--tc) 17%, transparent), transparent 62%),
    linear-gradient(165deg, rgba(19, 39, 34, 0.9), rgba(6, 15, 14, 0.94));
  color: var(--ink);
  text-align: left;
  cursor: pointer;
  box-shadow: 0 16px 36px rgba(0, 0, 0, 0.34);
  transition: transform 0.2s ease, border-color 0.2s ease, box-shadow 0.25s ease;
  overflow: hidden;
}
.starter-choice::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.08), transparent 26%);
  opacity: 0.7;
}
.starter-choice:hover {
  transform: translateY(-4px);
  border-color: color-mix(in srgb, var(--tc) 60%, rgba(255, 255, 255, 0.16));
  box-shadow: 0 22px 46px rgba(0, 0, 0, 0.45);
}
.starter-choice.selected {
  border-color: var(--gold);
  box-shadow:
    0 0 0 1px rgba(233, 196, 122, 0.5),
    0 18px 42px rgba(0, 0, 0, 0.5),
    0 0 42px color-mix(in srgb, var(--tc) 24%, transparent);
  transform: translateY(-5px);
}
.starter-choice.selected::before {
  content: "";
  position: absolute;
  inset: -1px;
  border-radius: inherit;
  border: 1px solid rgba(255, 230, 173, 0.5);
  pointer-events: none;
}

.starter-type {
  position: relative;
  z-index: 1;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  align-self: flex-start;
  padding: 4px 8px 3px;
  border-radius: 999px;
  font-size: 0.55rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--ts);
  background: color-mix(in srgb, var(--tc) 14%, rgba(0, 0, 0, 0.3));
  border: 1px solid color-mix(in srgb, var(--tc) 34%, transparent);
}
.starter-type .icon { font-size: 0.95rem; color: var(--tc); }

.starter-art {
  position: relative;
  z-index: 1;
  display: block;
  height: clamp(82px, 12vh, 126px);
  margin: 1px -6px 3px;
}
.starter-art svg { width: 100%; height: 100%; display: block; filter: drop-shadow(0 10px 14px rgba(0, 0, 0, 0.4)); }

.starter-copy { position: relative; z-index: 1; display: flex; flex-direction: column; min-width: 0; }
.starter-copy strong {
  font-family: var(--serif);
  font-size: clamp(1.15rem, 1.8vw, 1.42rem);
  font-weight: 600;
  letter-spacing: 0.02em;
  color: #f4f7e8;
  line-height: 1.1;
}
.starter-copy em {
  margin-top: 2px;
  font-style: normal;
  font-size: 0.7rem;
  letter-spacing: 0.06em;
  color: var(--ts);
  opacity: 0.9;
}
.starter-rule {
  display: block;
  width: 30px;
  height: 1px;
  margin: 8px 0 7px;
  background: linear-gradient(90deg, var(--tc), transparent);
}
.starter-passive {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 0.66rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  color: var(--ink-soft);
}
.starter-passive .icon { font-size: 0.82rem; color: var(--gold); }

.starter-pick {
  position: relative;
  z-index: 1;
  margin-top: 10px;
  align-self: flex-start;
  padding: 4px 9px;
  border-radius: 999px;
  font-size: 0.52rem;
  font-weight: 800;
  letter-spacing: 0.18em;
  color: var(--muted);
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(0, 0, 0, 0.24);
}
.starter-choice.selected .starter-pick {
  color: #1a1206;
  background: linear-gradient(180deg, #ffe6ad, #d8ad63);
  border-color: #ffe6ad;
}

.title-actions {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: clamp(10px, 1.8vh, 20px);
}
.title-hint {
  margin: 0;
  font-size: 0.64rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--dim);
}

.title-note-card {
  position: fixed;
  z-index: 3;
  right: clamp(20px, 3.2vw, 52px);
  top: 50%;
  transform: translateY(-50%);
  width: 232px;
  padding: 18px 18px 16px;
  border-radius: 14px;
  border: 1px solid rgba(233, 196, 122, 0.22);
  border-left: 2px solid rgba(233, 196, 122, 0.6);
  background: linear-gradient(160deg, rgba(8, 20, 18, 0.82), rgba(5, 13, 12, 0.9));
  backdrop-filter: blur(12px);
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.4);
  text-align: left;
}
.note-eyebrow {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.56rem;
  font-weight: 800;
  letter-spacing: 0.22em;
  color: var(--gold);
  text-transform: uppercase;
}
.note-eyebrow .icon { font-size: 0.9rem; }
.title-note-card p {
  margin: 10px 0 0;
  font-size: 0.76rem;
  line-height: 1.6;
  color: var(--ink-soft);
}
.note-rule {
  display: block;
  width: 100%;
  height: 1px;
  margin: 13px 0 0;
  background: linear-gradient(90deg, rgba(233, 196, 122, 0.28), transparent);
}
.title-note-card p.note-small { color: var(--dim); font-size: 0.7rem; }

.title-footer {
  position: fixed;
  z-index: 3;
  left: 0;
  right: 0;
  bottom: max(16px, env(safe-area-inset-bottom));
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: clamp(14px, 4vw, 40px);
  padding: 0 20px;
  font-size: 0.56rem;
  font-weight: 700;
  letter-spacing: 0.24em;
  color: rgba(180, 198, 188, 0.55);
  text-transform: uppercase;
  pointer-events: none;
}
.title-footer span { display: inline-flex; align-items: center; gap: 7px; }
.title-footer .icon { font-size: 0.92rem; color: rgba(233, 196, 122, 0.65); }

@keyframes twinkle {
  0% { opacity: 0.18; }
  100% { opacity: 0.95; }
}
@keyframes moteDrift {
  0% { transform: translateY(18px) scale(0.7); opacity: 0; }
  18% { opacity: 0.85; }
  80% { opacity: 0.5; }
  100% { transform: translateY(-90px) scale(1.1); opacity: 0; }
}

/* ------------------------------------------------------------
   HUD
   ------------------------------------------------------------ */

.hud {
  position: relative;
  z-index: 20;
  height: 64px;
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 18px;
  padding: 0 clamp(12px, 2.4vw, 24px);
  border-bottom: 1px solid rgba(233, 196, 122, 0.14);
  background:
    linear-gradient(180deg, rgba(12, 28, 25, 0.96), rgba(6, 16, 14, 0.92));
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.3);
}
.hud-brand { display: flex; align-items: center; gap: 14px; min-width: 0; }
.hud-floor {
  display: flex;
  align-items: baseline;
  gap: 4px;
  padding-left: 14px;
  border-left: 1px solid rgba(255, 255, 255, 0.1);
  font-size: 0.56rem;
  font-weight: 700;
  letter-spacing: 0.18em;
  color: var(--dim);
  white-space: nowrap;
}
.hud-floor b { font-size: 0.86rem; color: var(--gold-hi); letter-spacing: 0.04em; }
.hud-floor i { font-style: normal; color: var(--dim); }

.hud-stats {
  display: flex;
  align-items: center;
  gap: 9px;
  margin-left: auto;
  min-width: 0;
}
.hud-hp { display: flex; align-items: center; gap: 7px; color: var(--danger); }
.hud-hp > .icon { font-size: 1rem; }

.hp-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}
.hp-track {
  position: relative;
  width: 132px;
  height: 8px;
  border-radius: 999px;
  background: rgba(0, 0, 0, 0.5);
  border: 1px solid rgba(255, 255, 255, 0.08);
  overflow: hidden;
}
.hp-track span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #4f9c74, #8fe0a3 70%, #c8f0ab);
  box-shadow: 0 0 10px rgba(143, 224, 163, 0.4);
  transition: width 0.35s ease;
}
.hp-track i {
  position: absolute;
  inset: 0 0 auto;
  height: 50%;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.25), transparent);
  border-radius: inherit;
}
.hp-bar b {
  font-size: 0.78rem;
  font-weight: 700;
  color: #dff2df;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.hp-bar b small { font-size: 0.68em; color: var(--dim); font-weight: 500; }
.hp-bar.hud .hp-track { width: clamp(72px, 9vw, 132px); }
.hp-bar.combat .hp-track { width: clamp(90px, 12vw, 160px); height: 9px; }

.stat-pill {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 10px;
  border-radius: 999px;
  border: 1px solid rgba(233, 196, 122, 0.13);
  background: rgba(255, 255, 255, 0.028);
  font-size: 0.76rem;
  font-weight: 700;
  color: var(--ink-soft);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.stat-pill .icon { font-size: 0.88rem; color: var(--gold); }

.hud-actions { display: flex; align-items: center; gap: 6px; }
.hud-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: 36px;
  padding: 0 10px;
  border-radius: 9px;
  border: 1px solid transparent;
  background: rgba(255, 255, 255, 0.035);
  color: var(--ink-soft);
  cursor: pointer;
  font-size: 0.65rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  transition: background 0.16s ease, color 0.16s ease, border-color 0.16s ease;
}
.hud-btn .icon { font-size: 1.08rem; }
.hud-btn:hover { background: rgba(233, 196, 122, 0.1); border-color: rgba(233, 196, 122, 0.25); color: var(--gold-hi); }

/* ------------------------------------------------------------
   Map
   ------------------------------------------------------------ */

.map-screen { display: flex; flex-direction: column; }

.map-layout {
  flex: 1;
  min-height: 0;
  display: grid;
  grid-template-columns: 258px minmax(0, 1fr) 296px;
  gap: 14px;
  padding: 14px clamp(12px, 2vw, 20px) 16px;
}

.run-aside, .route-aside {
  min-height: 0;
  overflow-y: auto;
  border-radius: 18px;
  border: 1px solid rgba(233, 196, 122, 0.12);
  background:
    radial-gradient(120% 60% at 50% 0%, rgba(41, 85, 70, 0.2), transparent 60%),
    linear-gradient(170deg, rgba(13, 29, 26, 0.88), rgba(6, 15, 13, 0.92));
  padding: 16px 15px;
  scrollbar-width: thin;
  scrollbar-color: rgba(233, 196, 122, 0.2) transparent;
}
.run-aside { display: flex; flex-direction: column; gap: 14px; }

.aside-heading {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  font-size: 0.58rem;
  font-weight: 800;
  letter-spacing: 0.2em;
  color: var(--gold);
  text-transform: uppercase;
}
.aside-heading em { font-style: normal; font-size: 0.54rem; color: var(--dim); letter-spacing: 0.12em; }

.ascent-track { display: flex; flex-direction: column-reverse; gap: 3px; }
.ascent-track i {
  height: 4px;
  border-radius: 99px;
  background: rgba(255, 255, 255, 0.06);
}
.ascent-track i.lit {
  background: linear-gradient(90deg, rgba(233, 196, 122, 0.25), var(--gold));
  box-shadow: 0 0 10px rgba(233, 196, 122, 0.28);
}

.aside-section { display: flex; flex-direction: column; gap: 8px; }
.aside-title {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.56rem;
  font-weight: 800;
  letter-spacing: 0.18em;
  color: var(--muted);
  text-transform: uppercase;
}
.aside-title .icon { font-size: 0.86rem; color: var(--gold); }
.aside-title span { margin-left: auto; color: var(--gold); }

.party-list { display: flex; flex-direction: column; gap: 5px; }
.beast-mini {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  padding: 4px 6px 4px 4px;
  border-radius: 9px;
  background: rgba(255, 255, 255, 0.028);
  border: 1px solid rgba(255, 255, 255, 0.045);
}
.beast-mini-art {
  width: 32px;
  height: 32px;
  flex: 0 0 32px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: radial-gradient(circle at 50% 40%, rgba(126, 230, 201, 0.14), rgba(0, 0, 0, 0.16));
  overflow: hidden;
}
.beast-mini-art svg { width: 30px; height: 30px; }
.beast-mini-name {
  font-size: 0.7rem;
  font-weight: 600;
  color: var(--ink-soft);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.relic-list { display: flex; flex-direction: column; gap: 6px; }
.relic-chip {
  display: flex;
  gap: 8px;
  align-items: flex-start;
  padding: 7px;
  border-radius: 10px;
  background: linear-gradient(150deg, rgba(233, 196, 122, 0.06), rgba(0, 0, 0, 0.12));
  border: 1px solid rgba(233, 196, 122, 0.1);
}
.relic-chip .beast-mini { padding: 0; background: none; border: 0; flex: 0 0 32px; }
.relic-chip .beast-mini-name { display: none; }
.relic-chip > span:last-child { display: flex; flex-direction: column; min-width: 0; }
.relic-chip b { font-size: 0.64rem; color: var(--gold-hi); letter-spacing: 0.03em; }
.relic-chip em { font-style: normal; font-size: 0.58rem; line-height: 1.35; color: var(--dim); }

.aside-foot {
  margin-top: auto;
  padding-top: 12px;
  border-top: 1px solid rgba(255, 255, 255, 0.06);
  font-family: var(--serif);
  font-style: italic;
  font-size: 0.66rem;
  line-height: 1.5;
  color: var(--dim);
}
.aside-foot .icon { color: var(--gold-deep); }

.map-stage {
  position: relative;
  min-height: 0;
  display: flex;
  flex-direction: column;
  border-radius: 20px;
  border: 1px solid rgba(233, 196, 122, 0.14);
  background:
    radial-gradient(100% 60% at 50% 0%, rgba(37, 84, 69, 0.22), transparent 65%),
    linear-gradient(180deg, rgba(10, 24, 21, 0.9), rgba(4, 11, 10, 0.96));
  overflow: hidden;
  box-shadow: var(--shadow);
}
.map-caption {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 11px 16px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
  background: rgba(0, 0, 0, 0.16);
  font-size: 0.58rem;
  font-weight: 800;
  letter-spacing: 0.2em;
  color: var(--gold);
  text-transform: uppercase;
}
.map-caption > span { display: inline-flex; align-items: center; gap: 7px; }
.map-caption .icon { font-size: 0.95rem; }
.map-caption em { font-style: normal; font-weight: 500; letter-spacing: 0.1em; color: var(--dim); }

.map-scroll {
  position: relative;
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  scrollbar-width: thin;
  scrollbar-color: rgba(233, 196, 122, 0.22) transparent;
  scroll-behavior: smooth;
}
.map-scroll::-webkit-scrollbar { width: 8px; }
.map-scroll::-webkit-scrollbar-thumb { background: rgba(233, 196, 122, 0.2); border-radius: 99px; }

.map-canvas {
  position: relative;
  width: min(600px, 100%);
  aspect-ratio: 640 / 1330;
  margin: 0 auto;
  background:
    radial-gradient(70% 36% at 52% 24%, rgba(233, 196, 122, 0.06), transparent 70%),
    radial-gradient(90% 40% at 50% 100%, rgba(37, 85, 70, 0.18), transparent 68%),
    linear-gradient(180deg, #081613 0%, #071210 55%, #06100e 100%);
  overflow: hidden;
}
.map-canvas::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(126, 230, 201, 0.035) 1px, transparent 1px),
    linear-gradient(90deg, rgba(126, 230, 201, 0.03) 1px, transparent 1px);
  background-size: 64px 64px;
  mask-image: radial-gradient(80% 70% at 50% 50%, #000, transparent);
  pointer-events: none;
}
.map-decor { position: absolute; inset: 0; width: 100%; height: 100%; pointer-events: none; }
.map-lines { position: absolute; inset: 0; width: 100%; height: 100%; pointer-events: none; overflow: visible; }

.map-edge {
  fill: none;
  stroke: rgba(160, 190, 178, 0.17);
  stroke-width: 2;
  stroke-dasharray: 3 7;
  stroke-linecap: round;
}
.map-edge.walked {
  stroke: rgba(233, 196, 122, 0.58);
  stroke-width: 3;
  stroke-dasharray: none;
  filter: drop-shadow(0 0 5px rgba(233, 196, 122, 0.35));
}
.map-edge.open {
  stroke: rgba(126, 230, 201, 0.75);
  stroke-width: 2.6;
  stroke-dasharray: 5 6;
  animation: edgeFlow 1.2s linear infinite;
}

.map-row-label {
  position: absolute;
  left: 9px;
  transform: translateY(-50%);
  font-family: var(--mono);
  font-size: 0.52rem;
  letter-spacing: 0.1em;
  color: rgba(180, 203, 192, 0.3);
  pointer-events: none;
}

.map-node {
  position: absolute;
  z-index: 4;
  width: clamp(34px, 5.2vw, 46px);
  height: clamp(34px, 5.2vw, 46px);
  transform: translate(-50%, -50%);
  display: grid;
  place-items: center;
  padding: 0;
  border-radius: 50%;
  border: 1px solid rgba(178, 204, 192, 0.24);
  background:
    radial-gradient(circle at 50% 30%, rgba(255, 255, 255, 0.12), transparent 60%),
    linear-gradient(180deg, #1a302a, #0a1815);
  color: var(--ink-soft);
  cursor: pointer;
  box-shadow: 0 7px 16px rgba(0, 0, 0, 0.45);
  transition: transform 0.16s ease, border-color 0.16s ease, box-shadow 0.2s ease, color 0.16s ease;
}
.map-node .node-face { display: grid; place-items: center; font-size: clamp(0.9rem, 1.7vw, 1.25rem); }
.map-node .node-ring {
  position: absolute;
  inset: -5px;
  border-radius: 50%;
  border: 1px solid rgba(233, 196, 122, 0.12);
  pointer-events: none;
}
.map-node.locked { opacity: 0.38; cursor: default; filter: saturate(0.5); }
.map-node.visited {
  opacity: 0.52;
  color: var(--gold);
  border-color: rgba(233, 196, 122, 0.3);
  background: linear-gradient(180deg, #2a2b1e, #14140e);
  cursor: default;
}
.map-node.available {
  color: #fff8df;
  border-color: rgba(233, 196, 122, 0.85);
  background:
    radial-gradient(circle at 50% 30%, rgba(255, 236, 184, 0.44), transparent 62%),
    linear-gradient(180deg, #6d5a30, #2d2615);
  box-shadow:
    0 0 0 4px rgba(233, 196, 122, 0.08),
    0 0 26px rgba(233, 196, 122, 0.3),
    0 8px 18px rgba(0, 0, 0, 0.5);
  animation: nodePulse 2.4s ease-in-out infinite;
}
.map-node.available .node-ring { border-color: rgba(233, 196, 122, 0.42); animation: ringPulse 2.4s ease-out infinite; }
.map-node.available:hover {
  transform: translate(-50%, -50%) scale(1.14);
  border-color: #fff2c9;
  box-shadow: 0 0 0 5px rgba(233, 196, 122, 0.14), 0 0 34px rgba(233, 196, 122, 0.45);
  animation: none;
}
.map-node.elite.available, .map-node.boss.available {
  color: #ffd1df;
  border-color: rgba(241, 127, 155, 0.8);
  background:
    radial-gradient(circle at 50% 30%, rgba(241, 127, 155, 0.5), transparent 62%),
    linear-gradient(180deg, #4a2230, #210e15);
  box-shadow: 0 0 0 4px rgba(241, 127, 155, 0.08), 0 0 30px rgba(241, 127, 155, 0.28);
}
.map-node.boss { width: clamp(48px, 7vw, 62px); height: clamp(48px, 7vw, 62px); }

.node-check {
  position: absolute;
  right: -3px;
  bottom: -3px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: var(--gold);
  color: #201706;
  font-size: 0.6rem;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.4);
}
.node-check .icon { width: 10px; height: 10px; }

.map-start {
  position: absolute;
  z-index: 3;
  transform: translate(-50%, -50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  pointer-events: none;
}
.camp-fire {
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  color: #ffcf86;
  background: radial-gradient(circle, rgba(255, 173, 84, 0.3), rgba(255, 120, 40, 0.04));
  border: 1px solid rgba(255, 191, 112, 0.3);
  box-shadow: 0 0 28px rgba(255, 158, 61, 0.3);
}
.camp-fire .icon { width: 20px; height: 20px; }
.map-start b { font-size: 0.48rem; letter-spacing: 0.16em; color: var(--gold); }

.map-you {
  position: absolute;
  z-index: 6;
  transform: translate(-50%, -118%);
  display: flex;
  align-items: center;
  gap: 3px;
  padding: 3px 7px;
  border-radius: 999px;
  font-size: 0.46rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  color: #10221e;
  background: linear-gradient(180deg, #c8fbeb, #6fd6b8);
  box-shadow: 0 0 20px rgba(126, 230, 201, 0.45);
  pointer-events: none;
  animation: youBob 2.6s ease-in-out infinite;
}
.map-you .icon { width: 11px; height: 11px; }

.map-bottom-hint {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 8px;
  border-top: 1px solid rgba(255, 255, 255, 0.05);
  background: rgba(0, 0, 0, 0.16);
  font-size: 0.56rem;
  font-weight: 700;
  letter-spacing: 0.16em;
  color: var(--mint);
  text-transform: uppercase;
}
.map-bottom-hint .icon { font-size: 0.9rem; }

.route-aside { display: flex; flex-direction: column; gap: 12px; }
.route-card {
  padding: 15px;
  border-radius: 14px;
  border: 1px solid rgba(233, 196, 122, 0.13);
  background: linear-gradient(160deg, rgba(23, 46, 39, 0.72), rgba(7, 17, 15, 0.85));
}
.route-card.quiet { background: rgba(255, 255, 255, 0.022); border-color: rgba(255, 255, 255, 0.06); }
.route-kicker {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.52rem;
  font-weight: 800;
  letter-spacing: 0.2em;
  color: var(--gold);
  text-transform: uppercase;
}
.route-kicker .icon { font-size: 0.88rem; }
.route-card h2 {
  margin: 8px 0 4px;
  font-family: var(--serif);
  font-size: 1.22rem;
  font-weight: 600;
  line-height: 1.15;
  color: var(--ink);
}
.route-card p { margin: 0; font-size: 0.72rem; line-height: 1.55; color: var(--muted); }
.route-card p + p { margin-top: 8px; }
.route-card b { color: var(--gold-hi); }

.next-list { display: flex; flex-direction: column; gap: 6px; margin-top: 10px; }
.next-preview {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 7px 8px;
  border-radius: 9px;
  background: rgba(0, 0, 0, 0.2);
  border: 1px solid rgba(255, 255, 255, 0.05);
}
.next-icon {
  width: 28px;
  height: 28px;
  flex: 0 0 28px;
  display: grid;
  place-items: center;
  border-radius: 8px;
  color: var(--gold);
  background: rgba(233, 196, 122, 0.09);
  border: 1px solid rgba(233, 196, 122, 0.16);
}
.next-icon .icon { width: 16px; height: 16px; }
.next-preview span:last-child { display: flex; flex-direction: column; min-width: 0; }
.next-preview b { font-size: 0.66rem; color: var(--ink-soft); }
.next-preview em { font-style: normal; font-size: 0.56rem; color: var(--dim); line-height: 1.3; }
.next-preview.type-elite .next-icon, .next-preview.type-boss .next-icon {
  color: #ffc2d0;
  background: rgba(241, 127, 155, 0.1);
  border-color: rgba(241, 127, 155, 0.22);
}
.next-preview.type-rest .next-icon { color: #ffc984; background: rgba(255, 161, 75, 0.09); }
.next-preview.type-shop .next-icon { color: var(--gold); }

.bestiary-teaser .bestiary-count { display: flex; align-items: center; gap: 10px; margin-top: 8px; }
.bestiary-count b { font-family: var(--serif); font-size: 2rem; line-height: 1; color: var(--gold-hi); }
.bestiary-count span { font-size: 0.56rem; letter-spacing: 0.1em; line-height: 1.5; text-transform: uppercase; color: var(--dim); }

@keyframes edgeFlow { to { stroke-dashoffset: -22; } }
@keyframes nodePulse {
  0%, 100% { box-shadow: 0 0 0 4px rgba(233, 196, 122, 0.07), 0 0 20px rgba(233, 196, 122, 0.22), 0 8px 18px rgba(0, 0, 0, 0.5); }
  50% { box-shadow: 0 0 0 6px rgba(233, 196, 122, 0.11), 0 0 34px rgba(233, 196, 122, 0.36), 0 8px 18px rgba(0, 0, 0, 0.5); }
}
@keyframes ringPulse {
  0% { transform: scale(0.94); opacity: 1; }
  70%, 100% { transform: scale(1.35); opacity: 0; }
}
@keyframes youBob {
  0%, 100% { margin-top: 0; }
  50% { margin-top: -4px; }
}

/* ------------------------------------------------------------
   Cards
   ------------------------------------------------------------ */

.card {
  position: relative;
  width: var(--card-w);
  height: var(--card-h);
  flex: 0 0 auto;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  padding: 9px 9px 8px;
  border-radius: 13px;
  border: 1px solid color-mix(in srgb, var(--tc) 38%, rgba(255, 255, 255, 0.1));
  background:
    radial-gradient(120% 62% at 50% 0%, color-mix(in srgb, var(--tc) 20%, transparent), transparent 64%),
    linear-gradient(172deg, rgba(20, 40, 35, 0.98), rgba(7, 16, 14, 0.99));
  color: var(--ink);
  text-align: left;
  cursor: pointer;
  overflow: hidden;
  box-shadow:
    0 12px 26px rgba(0, 0, 0, 0.48),
    0 1px 0 rgba(255, 255, 255, 0.07) inset;
  transition: transform 0.18s ease, box-shadow 0.2s ease, border-color 0.18s ease, opacity 0.2s ease;
}
.card::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.07), transparent 22%),
    radial-gradient(80% 26% at 50% 100%, color-mix(in srgb, var(--tc) 12%, transparent), transparent);
}
.card::after {
  content: "";
  position: absolute;
  inset: 3px;
  border-radius: 10px;
  border: 1px solid rgba(255, 255, 255, 0.035);
  pointer-events: none;
}
.card:hover { border-color: color-mix(in srgb, var(--tc) 75%, #fff 10%); }

.card-cost {
  position: absolute;
  z-index: 3;
  top: 5px;
  left: 5px;
  width: 24px;
  height: 24px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  font-family: var(--serif);
  font-size: 0.92rem;
  font-weight: 700;
  color: #ffe9b6;
  background:
    radial-gradient(circle at 38% 30%, #4b5a42, #12201b 65%, #070e0c);
  border: 1px solid rgba(233, 196, 122, 0.66);
  box-shadow: 0 0 12px rgba(0, 0, 0, 0.55);
}

.card-art {
  position: relative;
  z-index: 1;
  height: 47px;
  flex: 0 0 47px;
  display: grid;
  place-items: center;
  margin: 0 0 4px;
  border-radius: 8px;
  background:
    radial-gradient(70% 90% at 50% 55%, color-mix(in srgb, var(--tc) 26%, transparent), transparent 72%),
    rgba(0, 0, 0, 0.22);
  overflow: hidden;
}
.card-art > .icon {
  width: 27px;
  height: 27px;
  color: var(--tc);
  stroke-width: 1.4;
  filter: drop-shadow(0 0 7px color-mix(in srgb, var(--tc) 55%, transparent));
  position: relative;
  z-index: 1;
}
.card-art > .orb-art { width: 44px; height: 44px; position: relative; z-index: 1; }
.card-art-glow {
  position: absolute;
  width: 60px;
  height: 26px;
  left: 50%;
  bottom: 4px;
  transform: translateX(-50%);
  border-radius: 50%;
  background: color-mix(in srgb, var(--tc) 38%, transparent);
  filter: blur(9px);
  opacity: 0.6;
}

.card-name {
  position: relative;
  z-index: 1;
  display: block;
  padding-right: 2px;
  font-family: var(--serif);
  font-size: 0.82rem;
  font-weight: 600;
  line-height: 1.04;
  letter-spacing: 0.015em;
  color: #f1f6e8;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.6);
  min-height: 1.04em;
}
.card-name sup { color: var(--gold); font-size: 0.7em; margin-left: 1px; }

.card-sub {
  position: relative;
  z-index: 1;
  display: block;
  margin-top: 2px;
  font-size: 0.43rem;
  font-weight: 700;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: color-mix(in srgb, var(--ts) 78%, #fff 6%);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.card-rule {
  position: relative;
  z-index: 1;
  display: block;
  width: 25px;
  height: 1px;
  flex: 0 0 1px;
  margin: 5px 0 5px;
  background: linear-gradient(90deg, var(--tc), transparent);
  opacity: 0.7;
}
.card-text {
  position: relative;
  z-index: 1;
  display: block;
  flex: 1;
  overflow: hidden;
  font-size: 0.58rem;
  line-height: 1.3;
  color: #cbd9cf;
  text-wrap: pretty;
}
.card-strike {
  position: absolute;
  right: 7px;
  bottom: 5px;
  z-index: 1;
  color: var(--tc);
  opacity: 0.4;
}
.card-strike .icon { width: 12px; height: 12px; }
.card-exhaust {
  position: absolute;
  right: 7px;
  bottom: 5px;
  z-index: 1;
  font-size: 0.4rem;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: #e1b189;
  opacity: 0.8;
}

.card.kind-power {
  border-color: color-mix(in srgb, var(--tc) 52%, rgba(255, 255, 255, 0.16));
  background:
    radial-gradient(100% 48% at 50% 0%, color-mix(in srgb, var(--tc) 28%, transparent), transparent 70%),
    linear-gradient(170deg, rgba(28, 48, 37, 0.98), rgba(8, 17, 14, 0.99));
}
.card.orb-card {
  border-color: rgba(233, 196, 122, 0.52);
  background:
    radial-gradient(90% 58% at 50% 20%, rgba(233, 196, 122, 0.26), transparent 70%),
    linear-gradient(170deg, rgba(43, 37, 22, 0.98), rgba(12, 16, 12, 0.99));
}
.card.orb-card .card-art { background: radial-gradient(70% 90% at 50% 55%, rgba(233, 196, 122, 0.3), transparent 74%); }
.card.orb-card .card-name { color: #fff1cb; }
.card.upgraded {
  border-color: rgba(233, 196, 122, 0.82);
  box-shadow:
    0 0 0 1px rgba(233, 196, 122, 0.18),
    0 12px 28px rgba(0, 0, 0, 0.5),
    0 0 22px rgba(233, 196, 122, 0.12);
}
.card.unplayable { opacity: 0.52; filter: saturate(0.55); cursor: not-allowed; }

#hand .card {
  --rot: calc((var(--i) - (var(--n) - 1) / 2) * 1.4deg);
  transform: rotate(var(--rot));
  transform-origin: 50% 128%;
}
#hand .card + .card { margin-left: clamp(-38px, -2vw, -22px); }
#hand .card.playable:hover {
  z-index: 8;
  transform: rotate(0deg) translateY(-24px) scale(1.07);
  border-color: color-mix(in srgb, var(--tc) 80%, #fff 16%);
  box-shadow:
    0 22px 40px rgba(0, 0, 0, 0.58),
    0 0 26px color-mix(in srgb, var(--tc) 24%, transparent);
}
#hand .card.playable { cursor: pointer; }

/* display grids should not fan */
.deck-grid .card, .upgrade-grid .card, .removal-grid .card {
  width: 100%;
  max-width: 150px;
  height: calc(var(--card-h) + 12px);
  margin: 0 auto;
  cursor: pointer;
}
.deck-grid .card:hover, .upgrade-grid .card:hover, .removal-grid .card:hover {
  transform: translateY(-4px);
  border-color: rgba(233, 196, 122, 0.7);
  box-shadow: 0 18px 34px rgba(0, 0, 0, 0.5);
}
.upgrade-grid .card, .removal-grid .card { cursor: pointer; }
.shop-card-wrap .card { cursor: default; }
.shop-card-wrap .card:hover { transform: none; }

.card-ghost {
  pointer-events: none !important;
  opacity: 1;
  box-shadow: 0 30px 60px rgba(0, 0, 0, 0.5);
}

/* ------------------------------------------------------------
   Combat stage
   ------------------------------------------------------------ */

.combat-screen {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto auto;
  background: #081310;
  overflow: hidden;
}

.combat-world { position: absolute; inset: 0; overflow: hidden; pointer-events: none; }
.combat-world::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(62% 46% at 50% 40%, rgba(44, 96, 80, 0.28), transparent 70%),
    linear-gradient(180deg, #0b211d 0%, #0a1a17 42%, #071310 100%);
}
.combat-moon {
  position: absolute;
  top: 9%;
  left: 50%;
  width: clamp(110px, 15vw, 190px);
  aspect-ratio: 1;
  transform: translateX(-50%);
  border-radius: 50%;
  background:
    radial-gradient(circle at 38% 34%, #fffbe4 0%, #f4dfa5 38%, #c8a866 68%, #7a5a33 100%);
  box-shadow:
    0 0 60px rgba(240, 215, 158, 0.18),
    0 0 160px rgba(240, 215, 158, 0.12);
  opacity: 0.8;
}
.combat-moon::after {
  content: "";
  position: absolute;
  inset: 12% 18%;
  border-radius: 50%;
  background:
    radial-gradient(circle at 30% 30%, rgba(160, 130, 78, 0.18) 0 12%, transparent 13%),
    radial-gradient(circle at 68% 55%, rgba(160, 130, 78, 0.15) 0 9%, transparent 10%),
    radial-gradient(circle at 45% 75%, rgba(160, 130, 78, 0.12) 0 7%, transparent 8%);
}
.combat-ridge {
  position: absolute;
  left: -5%;
  right: -5%;
  bottom: 0;
  background: linear-gradient(180deg, #0e2520, #04100d 70%);
}
.combat-ridge.ridge-back {
  height: 46%;
  clip-path: polygon(0 64%, 7% 48%, 13% 60%, 20% 34%, 27% 57%, 34% 43%, 41% 62%, 47% 40%, 54% 56%, 61% 34%, 68% 55%, 75% 41%, 82% 59%, 89% 44%, 96% 60%, 100% 50%, 100% 100%, 0 100%);
  opacity: 0.72;
}
.combat-ridge.ridge-mid {
  height: 30%;
  clip-path: polygon(0 60%, 6% 40%, 12% 66%, 19% 44%, 26% 70%, 33% 48%, 40% 74%, 48% 40%, 56% 66%, 63% 46%, 70% 70%, 77% 42%, 84% 64%, 91% 38%, 97% 62%, 100% 44%, 100% 100%, 0 100%);
  background: linear-gradient(180deg, #0a1c18, #030c0a 75%);
}
.combat-trees {
  position: absolute;
  left: -2%;
  right: -2%;
  bottom: 0;
  height: 42%;
  opacity: 0.9;
  background:
    repeating-linear-gradient(112deg, transparent 0 26px, rgba(2, 8, 7, 0.85) 27px 33px, transparent 34px 58px),
    repeating-linear-gradient(68deg, transparent 0 31px, rgba(2, 8, 7, 0.75) 32px 38px, transparent 39px 67px);
  mask-image: linear-gradient(180deg, transparent, #000 28%);
}
.combat-trees::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent, #030b09 72%);
}
.combat-fog {
  position: absolute;
  left: -20%;
  right: -20%;
  height: 26%;
  border-radius: 50%;
  filter: blur(24px);
  opacity: 0.5;
}
.fog-a {
  bottom: 20%;
  background: radial-gradient(60% 100% at 40% 50%, rgba(154, 196, 181, 0.16), transparent 70%);
  animation: fogDrift 24s ease-in-out infinite alternate;
}
.fog-b {
  bottom: 2%;
  background: radial-gradient(60% 100% at 65% 50%, rgba(154, 196, 181, 0.12), transparent 70%);
  animation: fogDrift 31s ease-in-out infinite alternate-reverse;
}
.arena-floor {
  position: absolute;
  left: 4%;
  right: 4%;
  bottom: 2%;
  height: 28%;
  border-radius: 50%;
  background:
    radial-gradient(closest-side, rgba(42, 82, 67, 0.42), rgba(10, 26, 21, 0.12) 62%, transparent 80%);
  border: 1px solid rgba(126, 230, 201, 0.06);
  transform: perspective(240px) rotateX(52deg);
  box-shadow: inset 0 0 80px rgba(126, 230, 201, 0.08);
}
.arena-floor span {
  position: absolute;
  inset: 22% 18%;
  border-radius: 50%;
  border: 1px solid rgba(233, 196, 122, 0.13);
}
.arena-runes {
  position: absolute;
  left: 50%;
  bottom: 5%;
  transform: translateX(-50%);
  display: flex;
  gap: 22px;
  color: rgba(233, 196, 122, 0.17);
  font-size: 0.8rem;
}

.combat-hud {
  position: relative;
  z-index: 8;
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 10px clamp(12px, 2.4vw, 24px) 6px;
  background: linear-gradient(180deg, rgba(4, 12, 10, 0.72), transparent);
}
.combat-loc { display: flex; align-items: center; gap: 9px; min-width: 0; }
.combat-loc > div { display: flex; flex-direction: column; min-width: 0; }
.combat-loc > div span {
  font-size: 0.5rem;
  font-weight: 700;
  letter-spacing: 0.17em;
  color: var(--dim);
}
.combat-loc > div b {
  font-family: var(--serif);
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--ink-soft);
  white-space: nowrap;
}
.back-btn { height: 34px; width: 34px; padding: 0; background: rgba(6, 15, 13, 0.55); border-color: rgba(255, 255, 255, 0.07); }

.combat-player-stat {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-left: auto;
  padding: 5px 10px;
  border-radius: 999px;
  background: rgba(5, 14, 12, 0.55);
  border: 1px solid rgba(241, 127, 155, 0.16);
  backdrop-filter: blur(8px);
}
.combat-player-stat > .icon { color: var(--danger); font-size: 0.95rem; }
.block-badge {
  display: flex;
  align-items: center;
  gap: 3px;
  padding: 2px 7px;
  border-radius: 999px;
  color: #c8ecff;
  background: rgba(67, 141, 182, 0.18);
  border: 1px solid rgba(116, 212, 237, 0.28);
  font-size: 0.7rem;
}
.block-badge .icon { font-size: 0.8rem; }
.combat-actions { display: flex; gap: 5px; }
.combat-actions .hud-btn { height: 34px; width: 36px; padding: 0; background: rgba(6, 15, 13, 0.5); border-color: rgba(255, 255, 255, 0.06); }

.arena {
  position: relative;
  z-index: 4;
  min-height: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) clamp(150px, 18vw, 230px) minmax(0, 1fr);
  align-items: center;
  gap: 8px;
  padding: 0 clamp(14px, 4vw, 62px);
}

.player-zone, .enemy-zone {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 0;
  min-height: 0;
}
.player-zone { justify-content: flex-end; padding-right: clamp(10px, 4vw, 54px); }
.enemy-zone { justify-content: flex-start; padding-left: clamp(10px, 4vw, 54px); flex-direction: column; }

.combatant {
  position: relative;
  width: clamp(180px, 20vw, 252px);
  max-width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
}
.enemy-combatant { width: clamp(190px, 22vw, 278px); }
.combatant-art {
  width: 100%;
  aspect-ratio: 1;
  max-height: min(31vh, 300px);
  display: grid;
  place-items: center;
  filter: drop-shadow(0 22px 26px rgba(0, 0, 0, 0.48));
}
.combatant-art svg { width: 100%; height: 100%; display: block; }
.player-svg .beast-body { animation: idleBreathe 4.4s ease-in-out infinite; }
.enemy-svg .beast-body { animation: idleBreathe 3.6s ease-in-out 0.6s infinite; }
.enemy-svg .beast-eyes { animation: eyeGlow 4s ease-in-out infinite; }

.combatant-plate {
  position: relative;
  z-index: 2;
  width: 100%;
  margin-top: -15px;
  padding: 8px 11px 9px;
  border-radius: 13px;
  border: 1px solid rgba(233, 196, 122, 0.19);
  background:
    linear-gradient(165deg, rgba(17, 37, 32, 0.95), rgba(5, 14, 12, 0.96));
  box-shadow: 0 14px 28px rgba(0, 0, 0, 0.45), 0 1px 0 rgba(255, 255, 255, 0.06) inset;
}
.plate-kicker {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 0.46rem;
  font-weight: 800;
  letter-spacing: 0.19em;
  color: var(--dim);
  text-transform: uppercase;
}
.combatant-plate > b {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  margin-top: 1px;
  font-family: var(--serif);
  font-size: 1.06rem;
  font-weight: 600;
  color: #f2f6e8;
}
.plate-block {
  display: inline-flex;
