}
.plate-block .icon { font-size: 0.75rem; }

.enemy-name-row { display: flex; align-items: center; justify-content: space-between; gap: 7px; margin-top: 1px; }
.enemy-name-row b { font-family: var(--serif); font-size: 1.05rem; font-weight: 600; line-height: 1.15; color: #f5f7e9; }
.type-badge {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 2px 6px 2px 5px;
  border-radius: 999px;
  font-size: 0.45rem;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--tc);
  border: 1px solid color-mix(in srgb, var(--tc) 38%, transparent);
  background: color-mix(in srgb, var(--tc) 12%, rgba(0, 0, 0, 0.25));
  white-space: nowrap;
}
.type-badge .icon { width: 0.85rem; height: 0.85rem; }

.enemy-hp-row { display: flex; align-items: center; gap: 7px; margin-top: 5px; }
.enemy-hp-track {
  position: relative;
  flex: 1;
  height: 8px;
  border-radius: 999px;
  background: rgba(0, 0, 0, 0.48);
  border: 1px solid rgba(255, 255, 255, 0.08);
  overflow: hidden;
}
.enemy-hp-track span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #b44538, #e97255 60%, #ffb079);
  box-shadow: 0 0 12px rgba(233, 114, 85, 0.45);
  transition: width 0.35s ease;
}
.enemy-hp-track i {
  position: absolute;
  inset: 0 0 auto;
  height: 50%;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.26), transparent);
}
.enemy-hp-row strong {
  font-size: 0.7rem;
  color: #ffe2dc;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.enemy-hp-row strong small { color: var(--dim); font-size: 0.8em; }
.enemy-block {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  font-size: 0.62rem;
  color: #c8ecff;
  padding: 1px 5px;
  border-radius: 999px;
  background: rgba(67, 141, 182, 0.16);
  border: 1px solid rgba(116, 212, 237, 0.24);
}
.enemy-block .icon { font-size: 0.7rem; }

.status-chips { display: flex; flex-wrap: wrap; gap: 3px; margin-top: 5px; }
.status-chip {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 1px 5px;
  border-radius: 5px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.045);
  font-size: 0.44rem;
  font-weight: 700;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--ink-soft);
}
.status-chip .icon { width: 0.7rem; height: 0.7rem; }
.status-chip b { color: #fff; font-size: 0.56rem; }
.status-chip em { font-style: normal; opacity: 0.6; font-size: 0.8em; }
.status-chip.status-weak, .status-chip.status-vulnerable { color: #ffc4cf; border-color: rgba(241, 127, 155, 0.22); }
.status-chip.status-focus, .status-chip.status-instinct { color: #ffdfa0; border-color: rgba(233, 196, 122, 0.25); }
.status-chip.status-thorns { color: #b6e8a0; border-color: rgba(126, 230, 160, 0.2); }
.status-chip.status-burn { color: #ffb082; border-color: rgba(255, 138, 92, 0.25); }
.status-chip.status-catch { color: #ffe6ad; border-color: rgba(233, 196, 122, 0.3); }
.status-chip.status-stun { color: #d8c4ff; }
.status-empty { margin-top: 5px; font-size: 0.46rem; letter-spacing: 0.08em; text-transform: uppercase; color: rgba(143, 167, 158, 0.5); }

.bind-line { margin-top: 6px; }
.bind-line > span {
  display: block;
  font-size: 0.43rem;
  font-weight: 800;
  letter-spacing: 0.14em;
  color: var(--dim);
  text-transform: uppercase;
}
.bind-line.open > span { color: var(--gold); }
.bind-track {
  position: relative;
  height: 5px;
  margin-top: 3px;
  border-radius: 999px;
  background: rgba(0, 0, 0, 0.45);
  border: 1px solid rgba(255, 255, 255, 0.06);
}
.bind-track > i {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, rgba(233, 196, 122, 0.4), var(--gold));
}
.bind-track > b {
  position: absolute;
  top: -2px;
  bottom: -2px;
  width: 1px;
  background: rgba(255, 255, 255, 0.36);
  transform: translateX(-50%);
}
.bind-line > strong {
  float: right;
  margin-top: -15px;
  font-size: 0.62rem;
  color: var(--gold);
}

.intent-wrap { margin-bottom: 7px; min-height: 36px; display: flex; align-items: flex-end; }
.intent {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 5px 10px 5px 7px;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(5, 14, 12, 0.84);
  backdrop-filter: blur(6px);
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.35);
  animation: intentBob 2.8s ease-in-out infinite;
}
.intent-icon {
  width: 25px;
  height: 25px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.06);
}
.intent-icon .icon { width: 15px; height: 15px; }
.intent > div { display: flex; flex-direction: column; line-height: 1.1; }
.intent b { font-size: 0.74rem; color: #fff; }
.intent b em { font-style: normal; font-size: 0.66rem; opacity: 0.7; }
.intent span { font-size: 0.44rem; letter-spacing: 0.08em; text-transform: uppercase; color: var(--dim); }
.intent.attack { border-color: rgba(241, 127, 155, 0.3); }
.intent.attack .intent-icon { color: #ffb3c1; background: rgba(241, 127, 155, 0.12); }
.intent.defend .intent-icon { color: #a9e3ff; background: rgba(116, 212, 237, 0.12); }
.intent.buff .intent-icon { color: var(--gold); background: rgba(233, 196, 122, 0.12); }
.intent.heal .intent-icon { color: #a7e6b6; background: rgba(126, 230, 160, 0.12); }
.intent.debuff .intent-icon { color: #d8c4ff; background: rgba(183, 156, 255, 0.12); }
.intent.stunned .intent-icon { color: #ffe16b; background: rgba(255, 225, 107, 0.1); }

.arena-center {
  position: relative;
  z-index: 3;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  text-align: center;
  pointer-events: none;
}
.turn-banner {
  padding: 5px 11px;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(5, 14, 12, 0.65);
  font-size: 0.48rem;
  font-weight: 800;
  letter-spacing: 0.22em;
  color: var(--dim);
  text-transform: uppercase;
  backdrop-filter: blur(5px);
  transition: color 0.2s ease, border-color 0.2s ease;
}
.turn-banner.active {
  color: var(--mint);
  border-color: rgba(126, 230, 201, 0.34);
  box-shadow: 0 0 18px rgba(126, 230, 201, 0.12);
}
.combat-log {
  min-height: 34px;
  max-width: 210px;
  font-family: var(--serif);
  font-size: 0.74rem;
  font-style: italic;
  line-height: 1.35;
  color: rgba(218, 232, 220, 0.8);
  text-shadow: 0 2px 8px rgba(0, 0, 0, 0.7);
  text-wrap: balance;
}

.companion-spirits {
  position: absolute;
  left: clamp(-6px, 0vw, 10px);
  bottom: 58px;
  display: flex;
  flex-direction: column-reverse;
  gap: 2px;
  z-index: 1;
}
.spirit {
  width: clamp(26px, 3.4vw, 40px);
  height: clamp(26px, 3.4vw, 40px);
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: radial-gradient(circle at 50% 40%, rgba(126, 230, 201, 0.13), transparent 70%);
  border: 1px solid rgba(126, 230, 201, 0.12);
  opacity: 0.72;
  filter: drop-shadow(0 3px 6px rgba(0, 0, 0, 0.4));
}
.spirit svg { width: 100%; height: 100%; }

.aura-badge {
  position: absolute;
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 2px 7px;
  border-radius: 999px;
  font-size: 0.6rem;
  font-weight: 700;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(5, 14, 12, 0.75);
  z-index: 3;
}
.aura-badge .icon { font-size: 0.8rem; }
.aura-badge.focus { right: 2px; top: 40%; color: #ffdfa0; border-color: rgba(233, 196, 122, 0.25); }
.aura-badge.thorns { right: 4px; top: 50%; color: #b6e8a0; border-color: rgba(126, 230, 160, 0.25); }

.catch-aura {
  position: absolute;
  z-index: 0;
  top: 3%;
  left: 50%;
  width: 88%;
  aspect-ratio: 1;
  transform: translateX(-50%);
  border-radius: 50%;
  opacity: 0;
  background: radial-gradient(circle, rgba(233, 196, 122, 0.12), transparent 66%);
  pointer-events: none;
}
.catch-aura.catchable {
  opacity: 1;
  animation: catchPulse 2.2s ease-in-out infinite;
  border: 1px dashed rgba(233, 196, 122, 0.4);
}

.shake { animation: zoneShake 0.34s cubic-bezier(0.36, 0.07, 0.19, 0.97); }

/* ------------------------------------------------------------
   Combat dock / hand
   ------------------------------------------------------------ */

.combat-dock {
  position: relative;
  z-index: 10;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  gap: clamp(6px, 1.2vw, 16px);
  padding: 2px clamp(10px, 2vw, 20px) 8px;
  background: linear-gradient(180deg, transparent, rgba(3, 10, 8, 0.82) 26%, rgba(3, 10, 8, 0.96));
}

.piles { display: flex; align-items: flex-end; gap: 5px; padding-bottom: 7px; }
.pile {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0;
  width: 44px;
  padding: 6px 3px 5px;
  border-radius: 9px;
  border: 1px solid rgba(233, 196, 122, 0.12);
  background: rgba(255, 255, 255, 0.03);
  color: var(--muted);
  cursor: default;
}
.pile .icon { font-size: 0.95rem; color: var(--gold-deep); }
.pile b { font-size: 0.68rem; color: var(--ink-soft); line-height: 1.1; }
.pile span { font-size: 0.4rem; letter-spacing: 0.09em; text-transform: uppercase; color: var(--dim); }
.pile.exhausted .icon { color: var(--danger); }

.energy-orb {
  position: relative;
  width: 64px;
  height: 64px;
  flex: 0 0 64px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  margin-bottom: 8px;
  border-radius: 50%;
  background:
    radial-gradient(circle at 40% 32%, rgba(255, 244, 200, 0.22), rgba(233, 196, 122, 0.07) 48%, rgba(8, 18, 15, 0.9) 72%);
  border: 1px solid rgba(233, 196, 122, 0.32);
  box-shadow: 0 0 0 4px rgba(233, 196, 122, 0.04), 0 8px 20px rgba(0, 0, 0, 0.4);
  line-height: 1;
}
.energy-orb.ready {
  border-color: rgba(233, 196, 122, 0.7);
  box-shadow: 0 0 0 4px rgba(233, 196, 122, 0.07), 0 0 26px rgba(233, 196, 122, 0.18);
}
.energy-core {
  font-family: var(--serif);
  font-size: 1.55rem;
  font-weight: 700;
  color: var(--gold-hi);
  text-shadow: 0 0 14px rgba(233, 196, 122, 0.5);
}
.energy-orb small { font-size: 0.5rem; color: var(--dim); margin-top: -1px; }
.energy-orb em {
  font-style: normal;
  font-size: 0.36rem;
  letter-spacing: 0.16em;
  color: var(--dim);
  margin-top: 4px;
}

.hand-wrap { flex: 1; min-width: 0; display: flex; justify-content: center; overflow: visible; }
.hand {
  display: flex;
  align-items: flex-end;
  justify-content: center;
  min-height: calc(var(--card-h) + 22px);
  padding: 18px 14px 0;
  overflow: visible;
}
.empty-hand {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 18px 24px;
  margin-bottom: 46px;
  border-radius: 12px;
  border: 1px dashed rgba(233, 196, 122, 0.2);
  color: var(--dim);
  font-family: var(--serif);
  font-style: italic;
  font-size: 0.8rem;
}
.empty-hand .icon { font-size: 1.1rem; color: var(--gold-deep); }

.end-turn-wrap { display: flex; flex-direction: column; align-items: center; gap: 4px; padding-bottom: 5px; }
.btn-end {
  min-width: 132px;
  padding: 14px 18px;
  font-size: 0.7rem;
  color: #17231a;
  background: linear-gradient(180deg, #e9fceb 0%, #a8e7b9 45%, #6cc58d 100%);
  border-color: #d7f7dd;
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.6) inset,
    0 8px 22px rgba(108, 197, 141, 0.24);
}
.btn-end:hover { box-shadow: 0 1px 0 rgba(255, 255, 255, 0.7) inset, 0 10px 28px rgba(108, 197, 141, 0.38); }
.btn-end.disabled, .btn-end:disabled {
  opacity: 0.45;
  cursor: not-allowed;
  filter: grayscale(0.5);
  transform: none;
}
.key-hint { font-size: 0.44rem; letter-spacing: 0.1em; color: var(--dim); text-transform: uppercase; }

.combat-help-strip {
  position: relative;
  z-index: 8;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  padding: 5px 12px max(5px, env(safe-area-inset-bottom));
  background: rgba(2, 8, 7, 0.9);
  border-top: 1px solid rgba(255, 255, 255, 0.04);
  font-size: 0.48rem;
  letter-spacing: 0.1em;
  color: var(--dim);
  text-align: center;
  text-transform: uppercase;
}
.combat-help-strip .icon { color: var(--gold-deep); margin-right: 2px; }

.fx-layer { position: fixed; inset: 0; z-index: 70; pointer-events: none; overflow: hidden; }
.float-text {
  position: fixed;
  font-family: var(--serif);
  font-size: 1.5rem;
  font-weight: 700;
  color: #fff;
  text-shadow: 0 2px 8px rgba(0, 0, 0, 0.9);
  pointer-events: none;
  animation: floatUp 1.05s cubic-bezier(0.2, 0.7, 0.3, 1) forwards;
  white-space: nowrap;
}
.float-text.damage { color: #ffb3a6; }
.float-text.block { color: #bfe9ff; }
.float-text.blocked { color: #9fc9d6; font-size: 0.9rem; letter-spacing: 0.1em; text-transform: uppercase; }
.float-text.heal { color: #a9f0b5; }
.float-text.status { color: #ffe6ad; font-size: 0.86rem; letter-spacing: 0.08em; text-transform: uppercase; }
.float-text.energy { color: var(--gold); font-size: 1rem; }
.float-text.burn { color: #ffa06f; }
.float-text.catch { color: #fff5c4; font-size: 2rem; letter-spacing: 0.14em; }

.catch-burst {
  position: fixed;
  inset: 0;
  z-index: 88;
  display: grid;
  place-items: center;
  pointer-events: none;
}
.catch-ring {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 80px;
  height: 80px;
  border-radius: 50%;
  border: 2px solid rgba(233, 196, 122, 0.85);
  transform: translate(-50%, -50%);
  animation: catchRing 1.1s ease-out forwards;
}
.catch-ring.r2 { border-color: rgba(255, 244, 200, 0.55); animation-delay: 0.16s; }
.catch-orb { width: 92px; height: 92px; animation: catchOrbPop 1.2s ease-out forwards; filter: drop-shadow(0 0 24px rgba(233, 196, 122, 0.7)); }
.catch-orb svg { width: 100%; height: 100%; }
.catch-flash {
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 50% 50%, rgba(255, 246, 210, 0.75), transparent 42%);
  animation: catchFlash 0.7s ease-out forwards;
}

@keyframes idleBreathe {
  0%, 100% { transform: translateY(0) scale(1); }
  50% { transform: translateY(-3px) scale(1.012); }
}
@keyframes eyeGlow {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.82; }
}
@keyframes fogDrift {
  0% { transform: translateX(-4%) scaleX(1); opacity: 0.36; }
  100% { transform: translateX(5%) scaleX(1.1); opacity: 0.58; }
}
@keyframes intentBob {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-3px); }
}
@keyframes catchPulse {
  0%, 100% { transform: translateX(-50%) scale(0.98); opacity: 0.7; }
  50% { transform: translateX(-50%) scale(1.04); opacity: 1; }
}
@keyframes floatUp {
  0% { transform: translateY(8px) scale(0.85); opacity: 0; }
  16% { opacity: 1; transform: translateY(0) scale(1.06); }
  100% { transform: translateY(-54px) scale(1); opacity: 0; }
}
@keyframes zoneShake {
  0%, 100% { transform: translateX(0); }
  20% { transform: translateX(-7px) rotate(-0.6deg); }
  45% { transform: translateX(6px) rotate(0.5deg); }
  70% { transform: translateX(-4px); }
  86% { transform: translateX(2px); }
}
@keyframes catchRing {
  0% { transform: translate(-50%, -50%) scale(0.4); opacity: 1; }
  100% { transform: translate(-50%, -50%) scale(5.2); opacity: 0; }
}
@keyframes catchOrbPop {
  0% { transform: scale(0.2) rotate(-30deg); opacity: 0; }
  30% { transform: scale(1.15) rotate(6deg); opacity: 1; }
  60% { transform: scale(0.96) rotate(-2deg); }
  100% { transform: scale(1.7) rotate(8deg); opacity: 0; }
}
@keyframes catchFlash {
  0% { opacity: 0; }
  20% { opacity: 1; }
  100% { opacity: 0; }
}

/* ------------------------------------------------------------
   Modals & overlays
   ------------------------------------------------------------ */

.modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 60;
  display: grid;
  place-items: center;
  padding: max(16px, env(safe-area-inset-top)) max(14px, env(safe-area-inset-right)) max(16px, env(safe-area-inset-bottom)) max(14px, env(safe-area-inset-left));
  background:
    radial-gradient(80% 70% at 50% 40%, rgba(14, 36, 30, 0.35), rgba(2, 7, 6, 0.86));
  backdrop-filter: blur(9px) saturate(0.9);
  animation: fadeIn 0.22s ease-out;
}
.modal-shell {
  width: min(740px, 100%);
  max-height: min(90dvh, 940px);
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: clamp(18px, 2.8vw, 30px);
  border-radius: 22px;
  border: 1px solid rgba(233, 196, 122, 0.28);
  background:
    radial-gradient(110% 60% at 50% 0%, rgba(50, 94, 78, 0.26), transparent 64%),
    linear-gradient(170deg, #0d211d 0%, #081411 58%, #060f0d 100%);
  box-shadow:
    0 40px 100px rgba(0, 0, 0, 0.68),
    0 1px 0 rgba(255, 255, 255, 0.08) inset;
  animation: modalRise 0.3s cubic-bezier(0.2, 0.8, 0.2, 1);
  scrollbar-width: thin;
  scrollbar-color: rgba(233, 196, 122, 0.24) transparent;
}
.modal-backdrop.wide .modal-shell { width: min(1080px, 100%); }
.modal-shell::-webkit-scrollbar { width: 8px; }
.modal-shell::-webkit-scrollbar-thumb { background: rgba(233, 196, 122, 0.22); border-radius: 99px; }

.modal-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; margin-bottom: 16px; }
.modal-head h2 {
  margin: 3px 0 0;
  font-family: var(--serif);
  font-size: clamp(1.4rem, 3vw, 2rem);
  font-weight: 600;
  line-height: 1.1;
  color: var(--ink);
}
.modal-kicker {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.56rem;
  font-weight: 800;
  letter-spacing: 0.22em;
  color: var(--gold);
  text-transform: uppercase;
}
.modal-kicker .icon { font-size: 0.94rem; }
.modal-close {
  width: 38px;
  height: 38px;
  flex: 0 0 38px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(255, 255, 255, 0.035);
  color: var(--muted);
  cursor: pointer;
  transition: background 0.16s ease, color 0.16s ease, transform 0.16s ease;
}
.modal-close:hover { background: rgba(241, 127, 155, 0.12); color: #ffd6df; transform: rotate(90deg); }
.modal-close .icon { width: 16px; height: 16px; }

.modal-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 18px;
  padding-top: 14px;
  border-top: 1px solid rgba(255, 255, 255, 0.07);
  font-size: 0.7rem;
  color: var(--dim);
}
.modal-foot > span { display: inline-flex; align-items: center; gap: 6px; }
.modal-foot > span .icon { color: var(--gold-deep); }
.modal-small { margin: 12px 0 0; font-size: 0.68rem; color: var(--dim); }

/* Deck + grid cards */
.deck-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(122px, 1fr));
  gap: 14px 12px;
  padding: 4px 2px 6px;
}
.deck-grid .card { --card-w: 100%; }

/* Bonds */
.bonds-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 12px; }
.bond-card {
  display: grid;
  grid-template-columns: 108px minmax(0, 1fr);
  gap: 12px;
  padding: 12px;
  border-radius: 15px;
  border: 1px solid color-mix(in srgb, var(--tc) 28%, rgba(255, 255, 255, 0.06));
  background:
    radial-gradient(80% 70% at 20% 20%, color-mix(in srgb, var(--tc) 14%, transparent), transparent 68%),
    rgba(255, 255, 255, 0.022);
  overflow: hidden;
}
.bond-art {
  display: grid;
  place-items: center;
  align-self: center;
  width: 108px;
  height: 108px;
  border-radius: 50%;
  background: radial-gradient(circle, color-mix(in srgb, var(--tc) 14%, transparent), transparent 70%);
}
.bond-art svg { width: 100%; height: 100%; }
.bond-body { min-width: 0; }
.bond-body h3 { margin: 4px 0 0; font-family: var(--serif); font-size: 1.25rem; font-weight: 600; color: #f4f7e9; }
.bond-body > em { display: block; font-style: normal; font-size: 0.66rem; letter-spacing: 0.04em; color: var(--ts); }
.bond-body p { margin: 6px 0 8px; font-size: 0.68rem; line-height: 1.45; color: var(--muted); }
.bond-passive {
  padding: 6px 8px;
  border-radius: 8px;
  background: rgba(0, 0, 0, 0.22);
  border: 1px solid rgba(233, 196, 122, 0.1);
}
.bond-passive span { display: flex; align-items: center; gap: 4px; font-size: 0.55rem; font-weight: 800; letter-spacing: 0.1em; text-transform: uppercase; color: var(--gold); }
.bond-passive .icon { font-size: 0.8rem; }
.bond-passive b { display: block; margin-top: 2px; font-size: 0.63rem; font-weight: 500; line-height: 1.35; color: var(--ink-soft); }
.bond-sig { display: flex; align-items: baseline; gap: 6px; margin-top: 6px; font-size: 0.58rem; color: var(--dim); }
.bond-sig b { font-family: var(--serif); font-size: 0.72rem; color: var(--ts); font-weight: 600; }

/* Help */
.help-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 11px; }
.help-grid section {
  padding: 14px;
  border-radius: 13px;
  border: 1px solid rgba(255, 255, 255, 0.06);
  background: rgba(255, 255, 255, 0.024);
}
.help-icon {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border-radius: 10px;
  color: var(--gold);
  background: rgba(233, 196, 122, 0.1);
  border: 1px solid rgba(233, 196, 122, 0.16);
}
.help-icon .icon { width: 17px; height: 17px; }
.help-grid h3 { margin: 9px 0 4px; font-family: var(--serif); font-size: 1.02rem; font-weight: 600; color: var(--ink); }
.help-grid p { margin: 0; font-size: 0.72rem; line-height: 1.55; color: var(--muted); }
.help-tips { display: flex; flex-direction: column; gap: 4px; margin-top: 12px; font-size: 0.68rem; color: var(--dim); }
.help-tips span { display: flex; align-items: center; gap: 6px; }
.help-tips .icon { color: var(--gold-deep); }
.help-tips b { color: var(--ink-soft); font-weight: 600; }

/* Menu */
.menu-stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
  margin-bottom: 14px;
}
.menu-stats > div {
  padding: 10px;
  border-radius: 10px;
  background: rgba(0, 0, 0, 0.2);
  border: 1px solid rgba(255, 255, 255, 0.05);
  text-align: center;
}
.menu-stats span { display: block; font-size: 0.46rem; font-weight: 800; letter-spacing: 0.16em; color: var(--dim); text-transform: uppercase; }
.menu-stats b { display: block; margin-top: 3px; font-family: var(--serif); font-size: 1.3rem; color: var(--gold-hi); font-weight: 600; }
.menu-actions { display: flex; flex-wrap: wrap; gap: 8px; }
.menu-actions .btn { flex: 1 1 160px; }

/* Rest + events */
.event-hero {
  position: relative;
  padding: 4px 0 2px;
  text-align: center;
}
.event-hero h2 {
  margin: 6px 0;
  font-family: var(--serif);
  font-size: clamp(1.6rem, 3.6vw, 2.35rem);
  font-weight: 600;
  line-height: 1.1;
  color: var(--ink);
}
.event-hero > p { max-width: 520px; margin: 0 auto; font-size: 0.78rem; line-height: 1.6; color: var(--muted); }
.rest-hero { padding-top: 0; }
.camp-scene {
  position: relative;
  height: 76px;
  display: grid;
  place-items: center;
  margin-bottom: 4px;
}
.camp-moon {
  position: absolute;
  top: 4px;
  right: 26%;
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: radial-gradient(circle at 38% 34%, #fff7d6, #e6c886 55%, #a67b42);
  box-shadow: 0 0 30px rgba(233, 196, 122, 0.28);
  opacity: 0.85;
}
.camp-flame {
  position: relative;
  display: grid;
  place-items: center;
  width: 58px;
  height: 58px;
  border-radius: 50%;
  color: #ffc681;
  background: radial-gradient(circle, rgba(255, 165, 76, 0.3), transparent 70%);
  border: 1px solid rgba(255, 191, 112, 0.22);
  box-shadow: 0 0 50px rgba(255, 148, 61, 0.32);
}
.camp-flame .icon { width: 30px; height: 30px; animation: flameFlicker 1.8s ease-in-out infinite; }

.choice-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(190px, 1fr)); gap: 10px; margin-top: 16px; }
.choice-card {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
  min-height: 150px;
  padding: 15px;
  border-radius: 14px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background:
    linear-gradient(160deg, rgba(255, 255, 255, 0.045), rgba(0, 0, 0, 0.16));
  color: var(--ink);
  text-align: left;
  cursor: pointer;
  transition: transform 0.16s ease, border-color 0.16s ease, background 0.16s ease;
}
.choice-card:hover {
  transform: translateY(-3px);
  border-color: rgba(233, 196, 122, 0.5);
  background: linear-gradient(160deg, rgba(233, 196, 122, 0.08), rgba(0, 0, 0, 0.2));
}
.choice-icon {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  margin-bottom: 7px;
  border-radius: 50%;
  color: var(--gold);
  border: 1px solid rgba(233, 196, 122, 0.22);
  background: rgba(233, 196, 122, 0.08);
}
.choice-icon .icon { width: 17px; height: 17px; }
.choice-card strong { font-family: var(--serif); font-size: 1.06rem; font-weight: 600; line-height: 1.15; }
.choice-card em { font-style: normal; font-size: 0.66rem; font-weight: 700; letter-spacing: 0.04em; color: var(--gold); }
.choice-card > span:last-child { margin-top: auto; padding-top: 8px; font-size: 0.64rem; line-height: 1.4; color: var(--dim); }

/* Shop */
.shop-head { display: flex; align-items: center; gap: 13px; margin-bottom: 6px; }
.merchant-mark {
  width: 50px;
  height: 50px;
  flex: 0 0 50px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  color: var(--gold);
  border: 1px solid rgba(233, 196, 122, 0.3);
  background: radial-gradient(circle at 50% 35%, rgba(233, 196, 122, 0.16), rgba(0, 0, 0, 0.2));
}
.merchant-mark .icon { width: 24px; height: 24px; }
.shop-head h2 { margin: 2px 0 0; font-family: var(--serif); font-size: clamp(1.1rem, 2.4vw, 1.5rem); font-weight: 600; font-style: italic; line-height: 1.2; color: var(--ink-soft); }
.shop-gold {
  margin-left: auto;
  display: flex;
  align-items: baseline;
  gap: 5px;
  padding: 7px 12px;
  border-radius: 999px;
  background: rgba(233, 196, 122, 0.08);
  border: 1px solid rgba(233, 196, 122, 0.2);
  color: var(--gold);
  white-space: nowrap;
}
.shop-gold .icon { font-size: 1rem; align-self: center; }
.shop-gold b { font-size: 1.1rem; color: var(--gold-hi); font-variant-numeric: tabular-nums; }
.shop-gold span { font-size: 0.54rem; letter-spacing: 0.1em; color: var(--dim); text-transform: uppercase; }
.shop-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(158px, 1fr));
  gap: 10px;
  margin-top: 16px;
}
.shop-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 10px;
  border-radius: 13px;
  border: 1px solid rgba(255, 255, 255, 0.06);
  background: rgba(255, 255, 255, 0.02);
}
.shop-item.sold { opacity: 0.42; }
.shop-card-wrap { display: flex; justify-content: center; }
.shop-card-wrap .card { --card-w: 118px; --card-h: 168px; }
.shop-buy { display: flex; align-items: center; justify-content: space-between; gap: 8px; width: 100%; margin-top: 2px; }
.shop-price { display: inline-flex; align-items: center; gap: 4px; font-size: 0.78rem; font-weight: 700; color: var(--gold-hi); font-variant-numeric: tabular-nums; }
.shop-price .icon { color: var(--gold); font-size: 0.9rem; }
.shop-item.service { justify-content: space-between; padding: 14px 12px; }
.service-art {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  flex: 1;
  width: 100%;
  min-height: 130px;
  border-radius: 10px;
  border: 1px dashed rgba(241, 127, 155, 0.24);
  background: rgba(143, 41, 72, 0.06);
  text-align: center;
  color: var(--muted);
  font-size: 0.62rem;
  line-height: 1.5;
  padding: 10px;
}
.service-art > .icon { width: 24px; height: 24px; color: #e292a7; }
.service-art em { font-style: italic; color: var(--dim); }

/* Rewards */
.modal-backdrop.reward-modal .modal-shell { width: min(820px, 100%); }
.reward-head { text-align: center; }
.reward-seal {
  width: 54px;
  height: 54px;
  margin: 0 auto 8px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  color: var(--gold);
  border: 1px solid rgba(233, 196, 122, 0.32);
  background: radial-gradient(circle, rgba(233, 196, 122, 0.18), transparent 70%);
  box-shadow: 0 0 34px rgba(233, 196, 122, 0.16);
}
.reward-seal .icon { width: 26px; height: 26px; }
.reward-head h2 { margin: 6px 0 4px; font-family: var(--serif); font-size: clamp(1.5rem, 3.4vw, 2.1rem); font-weight: 600; color: var(--ink); }
.reward-head p { margin: 0; font-size: 0.74rem; color: var(--muted); }
.reward-gold {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  margin-top: 9px;
  padding: 5px 10px;
  border-radius: 999px;
  color: var(--gold-hi);
  border: 1px solid rgba(233, 196, 122, 0.22);
  background: rgba(233, 196, 122, 0.08);
  font-size: 0.72rem;
  font-weight: 700;
}
.reward-gold .icon { color: var(--gold); }
.reward-extra { margin-top: 6px; font-size: 0.68rem; color: #ffd6df; }
.reward-extra .icon { color: var(--danger); }
.reward-cards { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; margin-top: 18px; }
.reward-option {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 10px;
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.02);
  border: 1px solid rgba(255, 255, 255, 0.05);
}
.reward-option .card { --card-w: 100%; max-width: 158px; }
.reward-option .btn-take { width: 100%; max-width: 158px; }
.reward-flavor { margin-top: 12px; text-align: center; font-family: var(--serif); font-style: italic; font-size: 0.68rem; color: var(--dim); }
.reward-flavor .icon { color: var(--gold-deep); }

/* Catch reward */
.modal-backdrop.catch-reward .modal-shell { width: min(780px, 100%); }
.catch-modal {
  display: grid;
  grid-template-columns: 0.82fr 1.18fr;
  gap: 16px;
  align-items: center;
}
.catch-portrait {
  position: relative;
  display: grid;
  place-items: center;
  aspect-ratio: 1;
  border-radius: 18px;
  border: 1px solid color-mix(in srgb, var(--tc) 32%, transparent);
  background:
    radial-gradient(circle at 50% 46%, color-mix(in srgb, var(--tc) 24%, transparent), transparent 67%),
    rgba(0, 0, 0, 0.2);
  overflow: hidden;
}
.catch-portrait svg { width: 100%; height: 100%; position: relative; z-index: 2; }
.catch-stamp {
  position: absolute;
  z-index: 3;
  top: 12px;
  left: 12px;
  padding: 4px 9px;
  border-radius: 4px;
  border: 1px solid rgba(233, 196, 122, 0.6);
  color: var(--gold-hi);
  background: rgba(6, 15, 13, 0.7);
  font-size: 0.52rem;
  font-weight: 800;
  letter-spacing: 0.2em;
  transform: rotate(-6deg);
}
.catch-rings {
  position: absolute;
  inset: 12%;
  border-radius: 50%;
  border: 1px dashed rgba(233, 196, 122, 0.2);
  animation: slowSpin 28s linear infinite;
}
.catch-copy h2 { margin: 3px 0 0; font-family: var(--serif); font-size: clamp(1.9rem, 4vw, 2.7rem); font-weight: 600; line-height: 1; color: #fff8e6; }
.catch-copy > em { display: block; font-style: normal; font-size: 0.74rem; letter-spacing: 0.08em; color: var(--ts); }
.catch-meta { display: flex; align-items: center; gap: 8px; margin: 8px 0; flex-wrap: wrap; }
.catch-meta .reward-gold { margin-top: 0; }
.catch-copy > p { margin: 0; font-size: 0.72rem; line-height: 1.55; color: var(--muted); }
.catch-passive { margin-top: 10px; padding: 8px 10px; border-radius: 9px; background: rgba(0, 0, 0, 0.24); border: 1px solid rgba(233, 196, 122, 0.12); }
.catch-passive span { display: flex; align-items: center; gap: 5px; font-size: 0.56rem; font-weight: 800; letter-spacing: 0.1em; text-transform: uppercase; color: var(--gold); }
.catch-passive .icon { font-size: 0.85rem; }
.catch-passive b { display: block; margin-top: 2px; font-size: 0.66rem; font-weight: 500; color: var(--ink-soft); line-height: 1.4; }
.catch-card { display: flex; align-items: center; gap: 10px; margin-top: 10px; }
.catch-card > span { font-size: 0.56rem; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; color: var(--dim); }
.catch-card .card { --card-w: 100px; --card-h: 142px; margin-left: auto; }
.catch-card .card-art { height: 38px; flex-basis: 38px; }
.catch-card .card-text { font-size: 0.52rem; }
.catch-duplicate { margin-top: 8px; font-size: 0.64rem; color: var(--gold); }
.catch-duplicate .icon { color: var(--gold); }
.catch-foot { margin-top: 14px; }

/* Endings */
.modal-backdrop.ending-modal .modal-shell {
  width: min(700px, 100%);
  background:
    radial-gradient(120% 70% at 50% 0%, rgba(233, 196, 122, 0.14), transparent 62%),
    linear-gradient(170deg, #10241f 0%, #081411 60%, #060f0d 100%);
}
.ending-hero { position: relative; text-align: center; padding-top: 8px; }
.ending-moon {
  width: 62px;
  height: 62px;
  margin: 0 auto 10px;
  border-radius: 50%;
  background: radial-gradient(circle at 38% 32%, #fffae4, #eed49a 46%, #b2864b 74%, #6d4b29);
  box-shadow: 0 0 60px rgba(238, 212, 154, 0.28);
}
.ending-hero.defeat .ending-moon {
  background: radial-gradient(circle at 38% 32%, #c9c0d6, #8b7f9c 46%, #4c4258 74%, #241e2c);
  box-shadow: 0 0 50px rgba(139, 127, 156, 0.2);
}
.ending-hero h2 { margin: 6px 0 6px; font-family: var(--serif); font-size: clamp(1.7rem, 4vw, 2.45rem); font-weight: 600; line-height: 1.08; color: var(--ink); }
.ending-hero > p { max-width: 500px; margin: 0 auto; font-size: 0.76rem; line-height: 1.6; color: var(--muted); }
.ending-stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; margin-top: 18px; }
.ending-stats > div { padding: 10px 6px; border-radius: 10px; background: rgba(0, 0, 0, 0.22); border: 1px solid rgba(255, 255, 255, 0.05); }
.ending-stats span { display: block; font-size: 0.44rem; font-weight: 800; letter-spacing: 0.14em; color: var(--dim); text-transform: uppercase; }
.ending-stats b { display: block; margin-top: 3px; font-family: var(--serif); font-size: 1.18rem; font-weight: 600; color: var(--gold-hi); }
.ending-team { display: flex; flex-wrap: wrap; justify-content: center; gap: 5px; margin-top: 14px; }
.ending-team .beast-mini { border-color: rgba(233, 196, 122, 0.1); }
.ending-foot { align-items: center; }
.ending-actions { display: flex; gap: 8px; flex-wrap: wrap; }
.modal-backdrop.ending-modal .modal-foot { border-top-color: rgba(233, 196, 122, 0.12); }

/* Toast */
.toast {
  display: flex;
  align-items: center;
  gap: 8px;
  max-width: min(360px, calc(100vw - 32px));
  padding: 10px 14px;
  border-radius: 10px;
  border: 1px solid rgba(233, 196, 122, 0.24);
  background: linear-gradient(160deg, rgba(20, 42, 36, 0.97), rgba(7, 17, 15, 0.98));
  color: var(--ink-soft);
  font-size: 0.72rem;
  font-weight: 600;
  box-shadow: 0 14px 34px rgba(0, 0, 0, 0.45);
  transform: translateY(12px);
  opacity: 0;
  transition: transform 0.26s ease, opacity 0.26s ease;
}
.toast.show { transform: translateY(0); opacity: 1; }
.toast .icon { color: var(--gold); font-size: 1rem; }
.toast.bad { border-color: rgba(241, 127, 155, 0.35); }
.toast.bad .icon { color: var(--danger); }
.toast.gold .icon { color: var(--gold-hi); }

/* ------------------------------------------------------------
   Responsive
   ------------------------------------------------------------ */

@media (max-width: 1240px) {
  :root { --card-w: 122px; --card-h: 178px; }
  .title-note-card { display: none; }
  .map-layout { grid-template-columns: 232px minmax(0, 1fr) 268px; gap: 12px; }
  .run-aside, .route-aside { padding: 14px 12px; }
  #hand .card + .card { margin-left: clamp(-40px, -3.4vw, -26px); }
}

@media (max-width: 1020px) {
  .run-aside { display: none; }
  .map-layout { grid-template-columns: minmax(0, 1fr) 268px; }
  .hud-floor { display: none; }
  .hud-stats { gap: 6px; }
  .stat-pill { padding: 5px 8px; font-size: 0.7rem; }
  .arena { padding: 0 clamp(8px, 2vw, 26px); }
  .player-zone { padding-right: 10px; }
  .enemy-zone { padding-left: 10px; }
  .combatant-art { max-height: min(28vh, 250px); }
  .companion-spirits { display: none; }
}

@media (max-width: 860px) {
  :root { --card-w: 108px; --card-h: 164px; }
  .map-layout { grid-template-columns: minmax(0, 1fr); padding: 10px; }
  .route-aside { display: none; }
  .map-stage { border-radius: 16px; }
  .map-canvas { width: min(520px, 100%); }
  .combat-screen { grid-template-rows: auto minmax(0, 1fr) auto auto; }
  .arena {
    grid-template-columns: 1fr 1fr;
    grid-template-rows: auto minmax(0, 1fr);
    align-items: end;
    padding: 2px 8px 0;
    gap: 0 4px;
  }
  .arena-center { grid-column: 1 / -1; grid-row: 1; flex-direction: row; justify-content: center; gap: 10px; }
  .combat-log { max-width: none; min-height: 0; font-size: 0.66rem; }
  .turn-banner { flex: 0 0 auto; }
  .player-zone { grid-column: 1; grid-row: 2; padding: 0 2px 0 0; }
  .enemy-zone { grid-column: 2; grid-row: 2; padding: 0 0 0 2px; }
  .combatant { width: min(34vw, 190px); }
  .enemy-combatant { width: min(36vw, 200px); }
  .combatant-art { max-height: min(24vh, 190px); }
  .combatant-plate { padding: 6px 8px 7px; border-radius: 10px; }
  .plate-kicker { font-size: 0.4rem; }
  .enemy-name-row b, .combatant-plate > b { font-size: 0.85rem; }
  .enemy-hp-row { gap: 4px; }
  .enemy-hp-row strong { font-size: 0.6rem; }
  .status-chip em { display: none; }
  .bind-line > span { font-size: 0.38rem; }
  .intent-wrap { margin-bottom: 4px; min-height: 30px; }
  .intent { padding: 3px 8px 3px 5px; }
  .intent-icon { width: 21px; height: 21px; }
  .intent b { font-size: 0.66rem; }
  .intent span { font-size: 0.38rem; }
  .combat-hud { padding: 6px 10px 2px; }
  .combat-actions .hud-btn { width: 32px; height: 30px; }
  .combat-player-stat { padding: 3px 7px; }
  .combat-loc > div span { display: none; }
  .combat-loc > div b { font-size: 0.8rem; }
  .back-btn { width: 30px; height: 30px; }
  .piles { display: none; }
  .energy-orb { width: 54px; height: 54px; flex-basis: 54px; }
  .energy-core { font-size: 1.25rem; }
  .btn-end { min-width: 100px; padding: 12px 12px; font-size: 0.62rem; }
  .combat-help-strip { display: none; }
  .hand { padding: 14px 8px 0; min-height: calc(var(--card-h) + 16px); }
  .combat-dock { padding: 2px 6px 10px; gap: 4px; }
  #hand .card + .card { margin-left: -30px; }
  .deck-grid { grid-template-columns: repeat(auto-fill, minmax(104px, 1fr)); gap: 10px 8px; }
  .deck-grid .card { height: 168px; }
  .bonds-grid { grid-template-columns: 1fr; }
  .bond-card { grid-template-columns: 84px minmax(0, 1fr); }
  .bond-art { width: 84px; height: 84px; }
  .help-grid { grid-template-columns: 1fr; }
  .reward-cards { gap: 8px; }
  .reward-option { padding: 7px; }
  .shop-grid { grid-template-columns: repeat(auto-fill, minmax(140px, 1fr)); }
  .catch-modal { grid-template-columns: 1fr; gap: 10px; }
  .catch-portrait { max-width: 260px; margin: 0 auto; width: 100%; }
  .catch-card .card { margin-left: auto; }
  .modal-shell { max-height: 92dvh; }
