import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const out = '/home/runner/work/PlayGround/PlayGround/screenshots';
mkdirSync(out, { recursive: true });

const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const results = [];
for (const [name, width, height] of [['desktop', 1440, 900], ['mobile', 390, 844]]) {
  const page = await browser.newPage({ viewport: { width, height } });
  page.setDefaultTimeout(20000);
  const errors = [];
  page.on('pageerror', e => errors.push('pageerror: ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  page.on('response', r => { if (r.status() >= 400) errors.push(`HTTP ${r.status()} ${r.url()}`); });
  await page.goto('http://localhost:3000', { waitUntil: 'load' });
  await page.waitForTimeout(900);
  await page.screenshot({ path: join(out, `title-${name}.png`) });
  const metrics = await page.evaluate(() => ({
    scrollW: document.documentElement.scrollWidth,
    clientW: document.documentElement.clientWidth,
    scrollH: document.documentElement.scrollHeight,
    clientH: document.documentElement.clientHeight,
    titleRect: (() => { const r = document.querySelector('.title-content')?.getBoundingClientRect(); return r && { top: r.top, bottom: r.bottom, height: r.height }; })(),
    cards: [...document.querySelectorAll('.starter-choice')].map(el => { const r = el.getBoundingClientRect(); return { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) }; }),
    start: (() => { const el = document.querySelector('#start-game'); const r = el?.getBoundingClientRect(); return r && { text: el.textContent.trim(), x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) }; })(),
  }));
  results.push({ name, errors, metrics });

  await page.getByRole('button', { name: 'Start Game' }).click();
  await page.waitForTimeout(1000);
  await page.screenshot({ path: join(out, `map-${name}.png`) });
  const mapInfo = await page.evaluate(() => ({
    nodes: document.querySelectorAll('.map-node').length,
    available: document.querySelectorAll('.map-node.available').length,
    mapCanvas: (() => { const r = document.querySelector('.map-canvas')?.getBoundingClientRect(); return r && { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) }; })(),
    mapScroll: (() => { const el = document.querySelector('#map-scroll'); return el && { scrollTop: Math.round(el.scrollTop), scrollHeight: el.scrollHeight, clientHeight: el.clientHeight }; })(),
    asideVisible: getComputedStyle(document.querySelector('.run-aside')).display,
  }));
  results.push({ name: name + '-map', errors: [...errors], mapInfo });

  const node = page.locator('.map-node.available').first();
  await node.click();
  await page.waitForTimeout(1200);
  await page.screenshot({ path: join(out, `combat-${name}.png`) });
  const combatInfo = await page.evaluate(() => {
    const hand = document.querySelector('#hand');
    const cards = [...document.querySelectorAll('#hand .card')];
    return {
      screen: document.querySelector('.combat-screen')?.dataset.phase,
      enemy: document.querySelector('.enemy-name-row b')?.textContent,
      handCount: cards.length,
      energy: document.querySelector('.energy-core')?.textContent,
      handRect: hand && (() => { const r = hand.getBoundingClientRect(); return { x: Math.round(r.x), w: Math.round(r.width), h: Math.round(r.height) }; })(),
      cardRects: cards.map(c => { const r = c.getBoundingClientRect(); return { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height), name: c.querySelector('.card-name')?.textContent }; }),
      dock: (() => { const r = document.querySelector('.combat-dock')?.getBoundingClientRect(); return r && { top: Math.round(r.top), bottom: Math.round(r.bottom), h: Math.round(r.height) }; })(),
      arena: (() => { const r = document.querySelector('.arena')?.getBoundingClientRect(); return r && { top: Math.round(r.top), bottom: Math.round(r.bottom), h: Math.round(r.height) }; })(),
      arenaOverflow: document.documentElement.scrollHeight > document.documentElement.clientHeight,
    };
  });
  results.push({ name: name + '-combat', errors: [...errors], combatInfo });

  const playable = page.locator('#hand .card.playable').first();
  if (await playable.count()) {
    await playable.click();
    await page.waitForTimeout(900);
    await page.screenshot({ path: join(out, `combat-played-${name}.png`) });
    const post = await page.evaluate(() => ({
      log: document.querySelector('.combat-log')?.textContent,
      energy: document.querySelector('.energy-core')?.textContent,
      handCount: document.querySelectorAll('#hand .card').length,
      enemyHp: document.querySelector('.enemy-hp-row strong')?.textContent,
      playerHp: document.querySelector('.combat-player-stat .hp-bar b')?.textContent,
    }));
    results.push({ name: name + '-played', errors: [...errors], post });
  }
  await page.close();
}
console.log(JSON.stringify(results, null, 2));
await browser.close();

