input.content:
import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
await page.goto('http://localhost:3000');
await page.getByRole('button', { name: 'Start Game' }).click();
await page.waitForTimeout(600);
await page.locator('.map-node.available').first().click();
await page.waitForTimeout(1200);
const info = await page.evaluate(() => {
  const card = document.querySelector('#hand .card');
  const text = card?.querySelector('.card-text');
  const name = card?.querySelector('.card-name');
  const cs = text && getComputedStyle(text);
  return {
    cardHTML: card?.outerHTML.slice(0, 400),
    card: card && { clientWidth: card.clientWidth, scrollWidth: card.scrollWidth, display: getComputedStyle(card).display, align: getComputedStyle(card).alignItems },
    text: text && { clientWidth: text.clientWidth, scrollWidth: text.scrollWidth, clientHeight: text.clientHeight, scrollHeight: text.scrollHeight, width: cs.width, display: cs.display, whiteSpace: cs.whiteSpace, flex: cs.flex, minWidth: cs.minWidth, padding: cs.padding, font: cs.font },
    name: name && { clientWidth: name.clientWidth, scrollWidth: name.scrollWidth, width: getComputedStyle(name).width },
    enemyArt: document.querySelector('.enemy-svg')?.dataset.creature,
    playerArt: document.querySelector('.player-svg')?.dataset.creature,
  };
});
console.log(JSON.stringify(info, null, 2));
await browser.close();

