input.content:
import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const out = '/home/runner/work/PlayGround/PlayGround/screenshots';
mkdirSync(out, { recursive: true });
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.setDefaultTimeout(20000);
const errors = [];
page.on('pageerror', e => errors.push('pageerror: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
page.on('response', r => { if (r.status() >= 400) errors.push(`HTTP ${r.status()} ${r.url()}`); });
const log = [];
const shot = async name => { await page.screenshot({ path: join(out, name + '.png') }); log.push('shot ' + name); };

await page.addInitScript(() => { Math.random = () => 0.07; });
await page.goto('http://localhost:3000', { waitUntil: 'load' });
await page.evaluate(() => localStorage.clear());
await page.reload();
await page.waitForTimeout(700);

// Help modal
await page.locator('#title-help').click();
await page.waitForTimeout(300);
await shot('modal-help');
await page.keyboard.press('Escape');
await page.waitForTimeout(200);

// Start run
await page.getByRole('button', { name: 'Start Game' }).click();
await page.waitForTimeout(700);

// Deck + bonds
await page.locator('[data-action="deck"]').click();
await page.waitForTimeout(350);
await shot('modal-deck');
await page.keyboard.press('Escape');
await page.waitForTimeout(200);
await page.locator('[data-action="bonds"]').click();
await page.waitForTimeout(350);
await shot('modal-bonds');
await page.keyboard.press('Escape');
await page.waitForTimeout(200);

const fight = async (maxTurns = 14) => {
  for (let turn = 0; turn < maxTurns; turn++) {
    for (let i = 0; i < 14; i++) {
      if (await page.locator('.ending-modal').count()) return 'ending';
      const orb = page.locator('#hand .card.playable.orb-card').first();
      if (await orb.count()) {
        await orb.click();
        await page.waitForTimeout(1600);
        return 'orb';
      }
      const playable = page.locator('#hand .card.playable').first();
      if (!(await playable.count())) break;
      await playable.click();
      await page.waitForTimeout(430);
      if (await page.locator('.modal-backdrop.catch-reward').count()) return 'catch';
      if (await page.locator('.modal-backdrop.reward-modal').count()) return 'reward';
      if (await page.locator('.ending-modal').count()) return 'ending';
    }
    const end = page.locator('#end-turn');
    if (!(await end.count()) || await end.isDisabled()) return 'stuck';
    await end.click();
    await page.waitForTimeout(2800);
    if (await page.locator('.modal-backdrop.catch-reward').count()) return 'catch';
    if (await page.locator('.modal-backdrop.reward-modal').count()) return 'reward';
    if (await page.locator('.ending-modal').count()) return 'ending';
  }
  return 'timeout';
};

// First battle: fight until an orb can be played and catch.
await page.locator('.map-node.available.battle').first().click();
await page.waitForTimeout(1200);
let result = await fight();
log.push('battle1 result=' + result);
if (await page.locator('.modal-backdrop.catch-reward').count()) {
  await page.waitForTimeout(400);
  await shot('modal-catch');
  await page.locator('#catch-continue').click();
  await page.waitForTimeout(800);
  await shot('map-after-catch');
} else if (await page.locator('.modal-backdrop.reward-modal').count()) {
  await shot('modal-reward');
