}, selector);

const fight = async (maxTurns = 14) => {
  for (let turn = 0; turn < maxTurns; turn++) {
    for (let i = 0; i < 14; i++) {
      if (await page.locator('.ending-modal').count()) return 'ending';
      if (await page.locator('#hand .card.playable.orb-card').count()) {
        await domClick('#hand .card.playable.orb-card');
        await page.waitForTimeout(1800);
        return 'orb';
      }
      if (!(await page.locator('#hand .card.playable').count())) break;
      await domClick('#hand .card.playable');
      await page.waitForTimeout(430);
      if (await page.locator('.modal-backdrop.catch-reward').count()) return 'catch';
      if (await page.locator('.modal-backdrop.reward-modal').count()) return 'reward';
      if (await page.locator('.ending-modal').count()) return 'ending';
    }
    const endState = await page.evaluate(() => {
      const end = document.querySelector('#end-turn');
      if (!end || end.disabled) return false;
      end.click();
      return true;
    });
    if (!endState) return 'stuck';
    await page.waitForTimeout(2800);
    if (await page.locator('.modal-backdrop.catch-reward').count()) return 'catch';
    if (await page.locator('.modal-backdrop.reward-modal').count()) return 'reward';
    if (await page.locator('.ending-modal').count()) return 'ending';
  }
  return 'timeout';
};

