import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.setDefaultTimeout(20000);
const errors = [];
page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
await page.addInitScript(() => { Math.random = () => 0.07; });
await page.goto('http://localhost:3000', { waitUntil: 'load' });
await page.evaluate(() => localStorage.clear());
await page.reload();
await page.waitForTimeout(600);
await page.getByRole('button', { name: 'Start Game' }).click();
await page.waitForTimeout(700);
await page.evaluate(() => {
  const key = 'wildspire.run.v2';
  const run = JSON.parse(localStorage.getItem(key));
  const node = run.map.nodes.find((n) => n.floor === 10 && n.lane === 0);
  node.visited = true;
  run.currentNode = node.id;
  run.floor = 10;
  run.hp = 999; run.maxHp = 999;
  let n = Date.now();
  const deck = [];
  for (let i = 0; i < 14; i++) deck.push({ uid: 'x' + (n++), id: 'solar_fang', upgraded: true });
  for (let i = 0; i < 14; i++) deck.push({ uid: 'x' + (n++), id: 'stonewall', upgraded: true });
  run.deck = deck;
  localStorage.setItem(key, JSON.stringify(run));
});
await page.reload();
await page.waitForTimeout(400);
await page.getByRole('button', { name: 'Continue Run' }).click();
await page.waitForTimeout(700);
await page.locator('.map-node.available.boss').click();
await page.waitForTimeout(1200);
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/combat-boss.png' });

const domClick = (selector) => page.evaluate((sel) => {
  const el = document.querySelector(sel);
  if (!el) return false;
  el.click();
  return true;
}, selector);

for (let turn = 0; turn < 20; turn++) {
  const before = await page.evaluate(() => ({
    phase: document.querySelector('.combat-screen')?.dataset.phase,
    energy: document.querySelector('.energy-core')?.textContent,
    hand: [...document.querySelectorAll('#hand .card')].map((el) => el.className.split(' ').slice(0, 3).join(' ')),
    log: document.querySelector('.combat-log')?.textContent,
    ending: !!document.querySelector('.ending-modal'),
    reward: !!document.querySelector('.modal-backdrop.reward-modal'),
  }));
  console.log('turn', turn, JSON.stringify(before));
  if (before.ending) break;
  if (before.reward) break;
  for (let i = 0; i < 20; i++) {
    if (await page.locator('.ending-modal').count()) break;
    if (await page.locator('.modal-backdrop.reward-modal').count()) break;
    if (!(await page.locator('#hand .card.playable').count())) break;
    await domClick('#hand .card.playable');
    await page.waitForTimeout(300);
  }
  const acted = await page.evaluate(() => {
    const end = document.querySelector('#end-turn');
    if (!end || end.disabled) return false;
    end.click();
    return true;
  });
  if (!acted) {
    console.log('cannot end turn; waiting');
    await page.waitForTimeout(2500);
    continue;
  }
  await page.waitForTimeout(2200);
}
await page.waitForTimeout(800);
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/boss-end.png' });
const final = await page.evaluate(() => ({
  ending: document.querySelector('.ending-modal')?.innerText,
  phase: document.querySelector('.combat-screen')?.dataset.phase,
  log: document.querySelector('.combat-log')?.textContent,
  enemyHp: document.querySelector('.enemy-hp-row strong')?.textContent,
}));
console.log(JSON.stringify({ errors, final }, null, 2));
await browser.close();

