const modalState = () => page.evaluate(() => {
  if (document.querySelector('.ending-modal')) return 'ending';
  if (document.querySelector('.modal-backdrop.catch-reward')) return 'catch';
  if (document.querySelector('.modal-backdrop.reward-modal')) return 'reward';
  return '';
});

const waitForPlayer = async () => {
  for (let w = 0; w < 80; w++) {
    const result = await modalState();
    if (result) return result;
    const ready = await page.evaluate(() => {
      const end = document.querySelector('#end-turn');
      return document.querySelector('.combat-screen')?.dataset.phase === 'player' && end && !end.disabled;
    });
    if (ready) return 'player';
    await page.waitForTimeout(250);
  }
  return 'wait-timeout';
};

const playOne = async () => {
  for (const selector of ['#hand .card.playable.orb-card', '#hand .card.playable.kind-attack', '#hand .card.playable']) {
    const ok = await domClick(selector);
    if (ok) {
      await page.waitForTimeout(430);
      return true;
    }
  }
  return false;
};

const fight = async (maxTurns = 14) => {
  for (let turn = 0; turn < maxTurns; turn++) {
    const ready = await waitForPlayer();
    if (ready === 'ending' || ready === 'catch' || ready === 'reward') return ready;
    if (ready !== 'player') return ready;
    for (let i = 0; i < 16; i++) {
      const modal = await modalState();
      if (modal) {
        if (modal === 'catch') await page.waitForTimeout(1500);
        return modal;
      }
      if (!(await playOne())) break;
    }
    const endState = await page.evaluate(() => {
      const end = document.querySelector('#end-turn');
      if (!end || end.disabled) return false;
      end.click();
      return true;
    });
    if (!endState) continue;
    await page.waitForTimeout(700);
  }
  return 'timeout';
};

