import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const out = '/home/runner/work/PlayGround/PlayGround/screenshots';
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const errors = [];
async function run(viewport, suffix) {
  const page = await browser.newPage({ viewport });
  page.setDefaultTimeout(20000);
  page.on('pageerror', (e) => errors.push(suffix + ' pageerror: ' + e.message));
  page.on('console', (m) => { if (m.type() === 'error') errors.push(suffix + ' console: ' + m.text()); });
  await page.addInitScript(() => { Math.random = () => 0.07; });
  await page.goto('http://localhost:3000', { waitUntil: 'load' });
  await page.evaluate(() => localStorage.clear());
  await page.reload();
  await page.waitForTimeout(500);
  await page.screenshot({ path: join(out, 'title' + suffix + '.png') });
  await page.getByRole('button', { name: 'Start Game' }).click();
  await page.waitForTimeout(600);
  await page.locator('.map-node.available.battle, .map-node.available.catch').first().click();
  await page.waitForTimeout(900);
  await page.screenshot({ path: join(out, 'combat' + suffix + '.png') });
  await page.locator('[data-action="menu"]').click();
  await page.waitForTimeout(350);
  await page.screenshot({ path: join(out, 'modal-pause' + suffix + '.png') });
  await page.keyboard.press('Escape');
  await page.waitForTimeout(250);
  // Play nothing; let the wild win.
  for (let turn = 0; turn < 30; turn++) {
    if (await page.locator('.ending-modal').count()) break;
    const clicked = await page.evaluate(() => {
      const end = document.querySelector('#end-turn');
      if (!end || end.disabled) return false;
      end.click();
      return true;
    });
    await page.waitForTimeout(clicked ? 2400 : 500);
  }
  await page.waitForTimeout(600);
  await page.screenshot({ path: join(out, 'modal-defeat' + suffix + '.png') });
  const info = await page.evaluate(() => ({
    ending: document.querySelector('.ending-modal')?.innerText,
    hp: document.querySelector('.player-hp b')?.textContent,
    runSaved: !!localStorage.getItem('wildspire.run.v2'),
    meta: localStorage.getItem('wildspire.meta.v2'),
  }));
  console.log(suffix, JSON.stringify(info));
  await page.close();
}
await run({ width: 1440, height: 900 }, '');
await run({ width: 390, height: 844 }, '-mobile');
console.log(JSON.stringify({ errors }));
await browser.close();

