import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
for (let attempt = 0; attempt < 3; attempt++) {
  const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  page.setDefaultTimeout(30000);
  await page.goto('http://localhost:3000', { waitUntil: 'load' });
  await page.waitForFunction(() => document.fonts.status === 'loaded');
  const btn = page.locator('#start-game');
  const start = Date.now();
  try {
    await btn.click({ trial: true, timeout: 2000 });
    console.log(attempt, 'trial ok in', Date.now() - start, 'ms');
    await btn.click({ timeout: 2000, noWaitAfter: true });
    console.log(attempt, 'click ok');
  } catch (e) {
    console.log(attempt, 'failed in', Date.now() - start, 'ms:', e.message.split('\n').slice(0, 10).join('\n'));
    console.log(await page.evaluate(() => {
      const el = document.querySelector('#start-game');
      const r = el.getBoundingClientRect();
      const cs = getComputedStyle(el);
      return { r: [r.x, r.y, r.width, r.height], transform: cs.transform, transition: cs.transition, vis: cs.visibility, display: cs.display, opacity: cs.opacity, scrollH: document.documentElement.scrollHeight, clientH: document.documentElement.clientHeight };
    }));
  }
  await browser.close();
}

